    "notes": "Nicht verwechseln mit 后 als Wort für „hinten, danach“ (后门 (hòumén), 以后 (yǐhòu), 后来 (hòulái)): Dort ist 后 ein gewöhnlicher Bestandteil des Wortes, kein produktives Präfix. Nachgestellt bezeichnet 后 Generationen: 八零后 (bā líng hòu) „in den 80ern Geborene“, 九零后 (jiǔ líng hòu). Im selben Syllabus-Eintrag steht 亲— („pro-, -freundlich“).",
