    "explanation": "Als Halbpräfix (类前缀) drückt 亲 (qīn) aus, dass jemand oder etwas einer Sache nahesteht oder ihr zugeneigt ist, ähnlich wie „pro-“ oder „-freundlich“. In Politik und Medien: 亲政府 (qīnzhèngfǔ) „regierungsfreundlich“, 亲美 (qīn Měi) „proamerikanisch“, 亲西方 „prowestlich“, oft mit 派 als „Lager, Fraktion“ (亲美派). 亲民 (qīnmín) heißt „bürgernah, volksnah“, meist über Politiker oder Stil. In der Fachsprache: 亲水 (qīnshuǐ) „hydrophil, wasseranziehend“, 亲油 „lipophil“, meist mit 性: 亲水性 (qīnshuǐxìng). Das Gegenstück ist oft 反— („anti-“) oder in der Chemie 疏—, etwa 疏水 (shūshuǐ) „hydrophob“. Die Bildungen sind schriftsprachlich und fachlich.",
