    "explanation": "Diese Halbsuffixe (类后缀) hängen sich an Wörter oder Silben und bilden ganze Wortreihen:\n—观 (guān) – „-anschauung, -auffassung“: 世界观 (shìjièguān) „Weltanschauung“, 人生观, 价值观 (jiàzhíguān) „Wertvorstellungen“, 消费观.\n—鬼 (guǐ) – abwertend „-bold, -sack“ für Menschen mit einem Laster: 酒鬼 (jiǔguǐ) „Säufer“, 胆小鬼 (dǎnxiǎoguǐ) „Angsthase“, 小气鬼 (xiǎoqìguǐ) „Geizhals“, 懒鬼 (lǎnguǐ) „Faulpelz“.\n—界 (jiè) – „-welt, -kreise, Branche“: 教育界 (jiàoyùjiè) „Bildungswesen“, 科学界 (kēxuéjiè) „Wissenschaft (als Gemeinschaft)“, 商界 (shāngjiè) „Geschäftswelt“, 文艺界 (wényìjiè) „Kulturszene“.\n—然 (rán) – bildet Adverbien und Adjektive „so, -artig“: 显然 (xiǎnrán) „offensichtlich“, 突然 (tūrán) „plötzlich“, 果然 (guǒrán) „tatsächlich (wie erwartet)“, 偶然 (ǒurán) „zufällig“, 欣然 (xīnrán) „freudig“.\n—坛 (tán) – „-szene“ in Kunst und Sport: 文坛 (wéntán) „Literaturszene“, 体坛 (tǐtán) „Sportwelt“, 歌坛 (gētán) „Musikszene“, 影坛 (yǐngtán) „Filmwelt“.\n—为 (wéi) – bildet Verben „zu, als“: 成为 (chéngwéi), 认为 (rènwéi), 称为 (chēngwéi), 分为 (fēnwéi); außerdem Gradadverbien „äußerst, recht“: 极为 (jíwéi), 较为 (jiàowéi), 更为 (gèngwéi).\n—制 (zhì) – „-system, -ordnung“: 学分制 (xuéfēnzhì) „Leistungspunktesystem“, 会员制 (huìyuánzhì) „Mitgliedschaftssystem“, 合同制 (hétongzhì) „Vertragsanstellung“, 责任制 (zérènzhì) „Verantwortungssystem“.\nDie Bildungen sind meist schriftsprachlich; nur —鬼 ist ausgesprochen umgangssprachlich und abwertend.",
