    "meaning": "Gehobene Verben: sehnlichst wünschen, keineswegs sein, ausgenommen, sich (nicht) lohnen, kann man sagen …",
    "notes": "巴不得 (bābude) und 恨不得 (hènbude) liegen nah beieinander; 恨不得 drückt meist einen übersteigerten, nicht erfüllbaren Wunsch aus (恨不得飞回家), 巴不得 einen Wunsch, der sich erfüllen kann. 犯不着 (fànbuzháo) und 犯得着 (fàndezháo) sind die verneinte und die fragende Form desselben Ausdrucks.",
    "explanation": "Diese Verben gehören überwiegend zur Schriftsprache; einige (巴不得 (bābude), 犯不着 (fànbuzháo), 免不了 (miǎnbuliǎo)) sind dagegen typisch umgangssprachlich. Viele stehen nicht allein, sondern verlangen eine bestimmte Ergänzung.\n巴不得 (bābude) – „es kaum erwarten können, sehnlichst wünschen“; + Verb oder Satz, umgangssprachlich: 巴不得马上回家.\n并非 (bìngfēi) – „keineswegs sein“; weist eine Annahme zurück, schriftlich für 并不是 (bìng bú shì).\n除外 (chúwài) – „ausgenommen sein“; steht am Satzende: 节假日除外 „außer an Feiertagen“.\n犯不着 (fànbuzháo) – „es lohnt sich nicht, es ist unnötig“: 犯不着生气.\n犯得着 (fàndezháo) – „lohnt es sich?“; fast nur in rhetorischen Fragen: 犯得着吗？\n恨不得 (hènbude) – „am liebsten würde man …“; starker, oft unerfüllbarer Wunsch.\n可否 (kěfǒu) – schriftlich „ob … kann; kann man …?“: 可否告知.\n可谓 (kěwèi) – „man kann wohl sagen, kann als … gelten“: 可谓一举两得.\n免不了 (miǎnbuliǎo) – „unvermeidlich sein, nicht ausbleiben“.\n所谓 (suǒwèi) – „was man … nennt; sogenannt“.\n有所 (yǒusuǒ) – „in gewissem Maße“ + zweisilbiges Verb: 有所提高.\n予以 (yǔyǐ) – Amtssprache „etwas zuteilwerden lassen“ + zweisilbiges Verb: 予以表扬.",
