    "meaning": "keineswegs sein, es ist nicht so, dass … (schriftlich)",
    "formation": "Subjekt + 并非 + Nomen/Verbgruppe (，而是 …)",
    "explanation": "并非 (bìngfēi) verneint mit Nachdruck und weist eine naheliegende Annahme oder Erwartung zurück: „es ist keineswegs so, dass …“. Es entspricht dem gesprochenen 并不是 (bìng bú shì) und gehört vor allem in die Schriftsprache, in Reden und Kommentare. Danach können ein Nomen, eine Verbgruppe oder sogar eine weitere Verneinung stehen (并非不想 „nicht, dass er nicht wollte“). Häufig folgt eine Richtigstellung mit 而是 (ér shì) „sondern“ oder 只是 (zhǐshì) „nur“. 并非 enthält das „sein“ schon, denn 非 heißt „nicht sein“; 并非是 kommt zwar vor, gilt aber stilistisch als doppelt.",
    "notes": "Das Adverb 并 (bìng) mit 不/没 (并不难, 并没去) ist ein eigener Punkt (HSK 4). Nicht verwechseln mit 无非 (wúfēi) „nichts anderes als“ und 莫非 (mòfēi) „etwa …?“.",
