    "explanation": "所谓 (suǒwèi) bedeutet wörtlich „das, was man … nennt“. Steht es mit 的 vor einem Nomen, entspricht es oft dem deutschen „sogenannt“ und klingt dabei meist distanziert oder spöttisch: Der Sprecher zweifelt, dass die Bezeichnung zutrifft (所谓的专家 „die sogenannten Experten“). Neutral ist es, wenn ein Begriff erklärt oder zitiert wird, besonders mit einem Urheber davor: 人们所谓的 „was die Leute … nennen“. Der Begriff steht oft in Anführungszeichen. 所谓 ist in Schrift und gehobener Rede üblich.",
