    "explanation": "有所 (yǒusuǒ) zeigt an, dass eine Veränderung oder Eigenschaft in einem gewissen, eher begrenzten Maß vorhanden ist: 有所提高 „hat sich etwas verbessert“, 有所不同 (yǒusuǒ bùtóng) „ist in manchem verschieden“. Danach steht fast immer ein zweisilbiges Verb oder Adjektiv, das selbst kein Objekt mehr bekommt: nicht *有所提高水平, sondern 水平有所提高. Typische Verbindungen: 有所增加, 有所改善, 有所好转, 有所了解, 有所准备. Der Ausdruck ist sachlich und schriftsprachlich (Berichte, Nachrichten); im Alltag sagt man eher 提高了一些 oder 有点儿不同.",
