    "notes": "Ähnlich ist 给予 (jǐyǔ), das auch ein Nomen als Objekt nehmen kann (给予帮助). 加以 (jiāyǐ) bezeichnet dagegen eher die Bearbeitung einer Sache (加以研究, 加以改进), 予以 (yǔyǐ) eher eine Maßnahme gegenüber Personen (Lob, Strafe, Genehmigung).",
    "explanation": "予以 (yǔyǐ) gehört zur Amts- und Schriftsprache (Bekanntmachungen, Vorschriften, Bescheide). Es macht aus einem zweisilbigen Verb eine förmliche „Gewährung“: 予以批准 (yǔyǐ pīzhǔn) „genehmigen“, 予以奖励 (yǔyǐ jiǎnglì) „belohnen“, 予以处罚 „bestrafen“, 予以支持 „unterstützen“, 予以答复 „beantworten“. Das Verb danach bekommt kein Objekt; wer oder was betroffen ist, steht vorher, meist mit 对 (duì) oder 对于 (duìyú) eingeleitet oder als Thema am Satzanfang. Einsilbige Verben stehen nicht nach 予以. Gesprochen sagt man einfach 批准 (pīzhǔn), 奖励 (jiǎnglì) usw. oder 给 + Nomen.",
