    "explanation": "Drei Hinweiswörter aus sehr verschiedenen Registern:\n彼 (bǐ) – klassisch-schriftsprachlich „jener, der andere“; heute fast nur in festen Verbindungen: 彼此 (bǐcǐ) „einander“, 彼时 (bǐshí) „damals“, 此起彼伏 (cǐ qǐ bǐ fú) „mal hier, mal dort; in Wellen“, 知己知彼 (zhī jǐ zhī bǐ) „sich selbst und den Gegner kennen“.\n这么着 (zhèmezhe) – umgangssprachlich „so, auf diese Weise“; steht für eine ganze Handlung oder einen Vorschlag: 就这么着吧 „machen wir es so“, 要不这么着 „wie wäre es damit: …“.\n兹 (zī) – Amtssprache „hiermit“; am Anfang von Bescheinigungen und Bekanntmachungen: 兹证明 „hiermit wird bescheinigt“, 兹定于 „es wird hiermit festgesetzt“.",
