    "notes": "Viele weitere Verbindungen mit 何 sind eigene Punkte: 何必 (hébì) „wozu denn“, 何尝 (hécháng) „wann je …“, 何止 (hézhǐ) „weit mehr als“, 谈何容易 (tán hé róngyì) „leichter gesagt als getan“, 有何 (yǒu hé) + Nomen, 何以 (héyǐ) ……为 sowie 无论如何 (wúlùn rúhé) „auf jeden Fall“.",
    "explanation": "何 (hé) ist das klassische Fragewort und entspricht je nach Verbindung 什么 (shénme), 哪 (nǎ) oder 怎么 (zěnme). Es steht im modernen Chinesisch fast nie allein, sondern in festen Zweierverbindungen, die in Schrift und förmlicher Rede üblich sind: 何时 (héshí) „wann“, 何人 (hérén) „wer“, 何处 (héchù) „wo“, 何故 (hégù) „warum“, 为何 (wèihé) „warum“, 如何 (rúhé) „wie“, 何以 (héyǐ) „wodurch, warum“. Wie andere Fragewörter kann es auch unbestimmt gebraucht werden: 不知何故 (bù zhī hégù) „aus irgendeinem Grund“. Im Alltag klingen diese Formen steif; dort sagt man 什么时候 (shénme shíhou), 为什么 (wèishénme) und 怎么.",
