    "explanation": "Zählwörter für Nomen, meist in geschriebener Sprache:\n重 (chóng) – „Schicht, Lage“ für Hintereinander- oder Übereinanderliegendes: 万重山 „unzählige Bergketten“, 两重意思 „zwei Bedeutungsebenen“. Lesung chóng, nicht zhòng.\n截 (jié) – „Stück, Abschnitt“ von etwas Länglichem: 一截绳子 „ein Stück Seil“.\n缕 (lǚ) – „Strähne, Faden, Hauch“: 一缕头发, 一缕阳光 „ein Sonnenstrahl“.\n码 (mǎ) – „Sache, Angelegenheit“, umgangssprachlich, fast nur 一码事 (yì mǎ shì) / 两码事 (liǎng mǎ shì): 这是两码事 „das sind zwei verschiedene Dinge“.\n枚 (méi) – kleine, runde oder flache Gegenstände: 一枚硬币 „eine Münze“, 一枚奖牌, 一枚邮票; auch Raketen.\n摊 (tān) – „Lache, Pfütze“ für Flüssiges oder Breiiges: 一摊水.\n丸 (wán) – Pillen und Kügelchen, besonders in der traditionellen Medizin: 一丸药.\n则 (zé) – Texte in Abschnitten: 一则新闻 „eine Meldung“, 一则广告, 一则寓言.\n幢 (zhuàng) – Gebäude: 一幢楼 „ein Gebäude“, 一幢别墅.\n宗 (zōng) – „Posten, Fall“ bei Geschäften und Rechtsfällen: 一宗交易, 一宗案件.",
