    "formation": "Verb + 了 + 一/几 + 通 (+ Objekt)",
    "notes": "Als Zählwort für Nomen heißt es tōng: 一通电话 (yì tōng diànhuà) „ein Anruf“, 一通电报. Ähnliche Handlungs-Zählwörter: 顿 (dùn) für Schelte und Mahlzeiten, 番 (fān) für mühevolle oder ausführliche Handlungen, 阵 (zhèn) für kurze Phasen.",
    "explanation": "Als Zählwort für Handlungen wird 通 tòng gelesen (nicht tōng). Es fasst eine Handlung als ein zusammenhängendes, oft lautes, heftiges oder ungeordnetes Ganzes: 骂了一通 „eine Schimpftirade loslassen“, 乱说一通 „drauflosreden“, 发了一通脾气 „einen Wutausbruch haben“, 忙了一通 „eine ganze Weile herumwerkeln“, 打了三通鼓 „drei Runden getrommelt“. Meist steht 一 davor, und die Wendung klingt umgangssprachlich und oft leicht abwertend. Bei trennbaren Verben steht 一通 zwischen den Teilen (发了一通脾气).",
