    "explanation": "尤为 (yóuwéi) bedeutet „besonders, in besonderem Maße“ und hebt hervor, dass etwas unter mehreren Dingen herausragt. Es ist die schriftsprachliche Form von 尤其 (yóuqí) bzw. 特别 (tèbié) und steht vor zweisilbigen Adjektiven oder Verben wie 重视 (zhòngshì) und 关注 (guānzhù): 尤为重要, 尤为突出, 尤为关键, 尤为明显. Sehr häufig ist die Einleitung 尤为重要的是…… „besonders wichtig ist …“. Anders als 尤其 kann 尤为 nicht vor einem Nomen oder Satzteil stehen, der hervorgehoben werden soll: Man sagt 尤其是孩子 „vor allem Kinder“, aber nicht *尤为孩子. Einsilbige Adjektive folgen meist nicht.",
