    "meaning": "Gehobene Bereichsadverbien: alle, ausnahmslos, im Großen und Ganzen, nur, einzig, nichts als",
    "notes": "唯 wird auch 惟 geschrieben (惟独 (wéidú), 惟有 (wéiyǒu)). 一概 (yígài) und 概 (gài) beziehen sich auf Dinge oder Fälle, kaum auf Personen; für „alle Personen“ stehen 均 (jūn) oder 皆 (jiē).",
    "explanation": "Adverbien, die den Umfang einer Aussage festlegen; die meisten sind schriftsprachlich.\n大体 (dàtǐ) – „im Großen und Ganzen, weitgehend“: 大体相同.\n概 (gài) – „ausnahmslos, pauschal“, vor allem in Hinweisen: 概不退换 „Umtausch ausgeschlossen“.\n皆 (jiē) – „alle“, klassisch für 都: 人人皆知 (rénrén jiē zhī).\n尽 (jìn) – „ganz, völlig; lauter“: 不尽相同 „nicht ganz gleich“, 尽是 (jìn shì) „lauter“.\n均 (jūn) – „alle, jeweils“, Amtssprache: 均已完成.\n通通 (tōngtōng) – „alles, restlos“, umgangssprachlich: 通通拿走.\n统统 (tǒngtǒng) – wie 通通 „alles, restlos“: 统统扔掉.\n唯 (wéi) – „nur, allein“, meist in festen Verbindungen: 唯一 (wéiyī) „einzig“.\n唯独 (wéidú) – „einzig, ausgerechnet nur“; hebt eine Ausnahme hervor.\n唯有 (wéiyǒu) – „nur, allein“, oft mit 才: 唯有……才…….\n无非 (wúfēi) – „nichts anderes als, bloß“.\n一概 (yígài) – „ausnahmslos, pauschal“, meist bei Ablehnung: 一概不知.",
