    "formation": "(Alle/alles …)，唯独 + Person/Sache + Prädikat",
    "notes": "Es gibt auch die Schreibung 惟独 (wéidú). 唯有 (wéiyǒu) „nur (wenn)“ nennt dagegen oft eine Bedingung (唯有……才……), 唯一 (wéiyī) „einzig“ ist ein Adjektiv vor dem Nomen.",
    "explanation": "唯独 (wéidú) greift aus einer Gesamtheit eine einzige Ausnahme heraus: „nur …, ausgerechnet …“. Typisch ist die Zweiteilung: Der erste Satzteil nennt das Ganze, oft mit 都 oder 什么都, der zweite mit 唯独 die Abweichung (大家都同意了，唯独他反对). 唯独 steht vor dem Subjekt oder vor dem Prädikat des zweiten Teils. Oft schwingt Bedauern oder Verwunderung mit. Der Ausdruck ist in der Schriftsprache und in gepflegter Rede üblich; gesprochen sagt man meist 只有 (zhǐyǒu) oder einfach 就 (jiù): 就他反对.",
