    "notes": "Ebenfalls schriftlich für „alle“ ist 均 (jūn), etwas sachlicher und typisch für Amtstexte. Das bekannte Zitat 四海之内皆兄弟 (sì hǎi zhī nèi jiē xiōngdì) „alle Menschen sind Brüder“ stammt aus den Gesprächen des Konfuzius.",
    "explanation": "皆 (jiē) ist das klassische Gegenstück zu 都 (dōu): „alle, sämtlich, ausnahmslos“. Es fasst wie 都 das vorangehende Subjekt zusammen und steht direkt vor dem Prädikat. Heute begegnet es vor allem in Chengyu und festen Wendungen (人人皆知 (rénrén jiē zhī) „allgemein bekannt“, 皆大欢喜 (jiē dà huānxǐ) „alle sind zufrieden“, 比比皆是 (bǐbǐ jiē shì) „überall zu finden“) sowie in förmlichen Texten, häufig vor 为, 是 oder 有: 皆为正品 „alles Originalware“. Im Alltag wirkt es gestelzt; 皆 und 都 stehen nicht doppelt nebeneinander (*皆都).",
