    "notes": "姑且 (gūqiě) und 暂且 (zànqiě) heißen beide „vorläufig“; 姑且 hat zusätzlich den Beiklang des Nachgebens („lassen wir es mal gelten“). 历来 (lìlái) ist schriftlicher als 向来 (xiànglái) und bezieht sich eher auf Institutionen und Traditionen. 即 (jí) bedeutet außerhalb dieses Punkts auch „das heißt, nämlich“.",
    "explanation": "Diese Zeitadverbien gehören überwiegend zur Schrift- und Amtssprache; sie stehen vor dem Verb.\n姑且 (gūqiě) – „vorerst, einstweilen“: man lässt etwas als Notlösung oder unter Vorbehalt gelten.\n即 (jí) – „sogleich, sofort“, direkt vor meist einsilbigem Verb; häufig in 即可 (jíkě) „dann genügt es“.\n即时 (jíshí) – „unverzüglich, in Echtzeit“.\n届时 (jièshí) – „zu gegebener Zeit, dann“: verweist auf einen vorher genannten Termin, typisch in Ankündigungen.\n尽早 (jǐnzǎo) – „so früh wie möglich“.\n就此 (jiùcǐ) – „hiermit, an dieser Stelle“ (beenden, abbrechen).\n历来 (lìlái) – „seit jeher, schon immer“ (Traditionen, Haltungen).\n尚 (shàng) – „noch“ = 还, vor allem in 尚未 (shàngwèi) „noch nicht“.\n随即 (suíjí) – „gleich darauf, unmittelbar danach“ (erzählend).\n向来 (xiànglái) – „schon immer, stets“, auch für persönliche Gewohnheiten.\n一经 (yìjīng) – „sobald einmal …“, mit 就/便 im Folgeteil.\n暂且 (zànqiě) – „vorläufig, fürs Erste“.\n早日 (zǎorì) – „bald, baldmöglichst“, vor allem in Wünschen.",
