    "notes": "一旦 (yídàn) „falls einmal“ bezieht sich eher auf einen möglichen, oft unerwünschten Fall; 一经 (yìjīng) auf einen Vorgang, der eine feste Folge auslöst (Prüfung, Genehmigung, Verkauf). Nicht verwechseln mit 曾经 (céngjīng) „schon einmal, früher einmal“.",
    "explanation": "一经 (yìjīng) betont, dass eine Handlung nur ein einziges Mal geschehen muss, damit eine bestimmte Folge sofort oder endgültig eintritt: „sobald einmal …, kaum dass …“. Danach steht meist ein zweisilbiges Verb, das oft passivisch zu verstehen ist (entdecken, genehmigen, veröffentlichen, verkaufen); das Subjekt ist dann der betroffene Gegenstand: „Ware, sobald verkauft, …“. Im Folgeteil stehen häufig 就 (jiù), 便 (biàn) oder 即 (jí), oft zusammen mit 立即 (lìjí) oder 立刻 (lìkè). Typisch für Vorschriften, Verträge, Bekanntmachungen und Nachrichten; im Gespräch sagt man eher 一……就…… oder 只要 (zhǐyào) … 就 ….",
