    "explanation": "就此 (jiùcǐ) heißt „an diesem Punkt, hiermit“: Die Handlung geschieht genau jetzt bzw. an der erreichten Stelle und hat meist abschließenden Charakter. Typische Verben sind 结束 (jiéshù) „beenden“, 告别 (gàobié) „sich verabschieden“, 停止 (tíngzhǐ) „aufhören“, 分手 (fēnshǒu) „sich trennen“ und 中断 (zhōngduàn) „abbrechen“. Man hört es in offiziellen Ansagen („Die Sitzung ist hiermit beendet“) und liest es in Erzählungen, wenn etwas an einer Stelle endet. Verneint (没有就此……, 不能就此……) bedeutet es „damit (noch) nicht zu Ende“. Das Wort ist gehoben; im Alltag sagt man eher 到此为止 (dào cǐ wéizhǐ) oder einfach 就这样.",
