    "meaning": "Art-und-Weise-Adverbien (gehoben): eigenmächtig, wie gewohnt, mit aller Kraft, eigens, kategorisch …",
    "formation": "Subjekt + Adverb der Art und Weise + Verb(gruppe)",
    "explanation": "Diese Adverbien beschreiben, wie, mit welcher Haltung oder unter welchen Umständen gehandelt wird; viele sind schriftlich, einige abwertend.\n按理 (ànlǐ) / 按说 (ànshuō) – „normalerweise müsste …“ (Erwartung, die oft nicht eintrifft; 按说 gesprochener).\n百般 (bǎibān) – „auf jede erdenkliche Weise“.\n不由得 (bùyóude) – „unwillkürlich, kann nicht anders als“.\n趁机 (chènjī) – „die Gelegenheit nutzen“.\n趁早 (chènzǎo) – „rechtzeitig, lieber früher als später“.\n大肆 (dàsì) – „hemmungslos, in großem Stil“ (abwertend).\n断然 (duànrán) – „entschieden, kategorisch“.\n公然 (gōngrán) – „offen, unverhohlen“ (abwertend).\n火速 (huǒsù) – „schnellstens“.\n截然 (jiérán) – „völlig, scharf (getrennt)“, vor 不同 (bùtóng) oder 相反 (xiāngfǎn).\n竭力 (jiélì) – „nach Kräften“.\n尽情 (jìnqíng) – „nach Herzenslust“.\n就近 (jiùjìn) – „in der Nähe, am nächstgelegenen Ort“.\n刻意 (kèyì) – „bewusst, gezielt“.\n拼命 (pīnmìng) – „mit aller Gewalt, verzweifelt“.\n强行 (qiángxíng) – „gewaltsam, mit Zwang“.\n任意 (rènyì) – „beliebig, nach Belieben“.\n日趋 (rìqū) – „von Tag zu Tag mehr“.\n如期 (rúqī) – „termingerecht, wie geplant“.\n擅自 (shànzì) – „eigenmächtig“.\n私自 (sīzì) – „heimlich, ohne Erlaubnis“.\n特此 (tècǐ) – Amtssprache „hiermit (wird …)“.\n瞎 (xiā) – gesprochen „blind drauflos, planlos“.\n一并 (yíbìng) – „zusammen, in einem Zug“.\n一举 (yìjǔ) – „mit einem Schlag“.\n一手 (yìshǒu) – „eigenhändig, im Alleingang“.\n毅然 (yìrán) – „entschlossen, ohne zu zögern“.\n有意 (yǒuyì) – „absichtlich“.\n照常 (zhàocháng) – „wie gewöhnlich“.\n照例 (zhàolì) – „wie üblich, der Regel nach“.\n照样 (zhàoyàng) – „trotzdem genauso“.\n执意 (zhíyì) – „hartnäckig, gegen jeden Rat“.\n骤然 (zhòurán) – „plötzlich, jäh“.\n逐一 (zhúyī) – „einzeln, eins nach dem anderen“.\n专程 (zhuānchéng) – „eigens (für diesen Zweck angereist)“.",
