    "notes": "毅然 (yìrán) betont den Mut, einen schweren Entschluss zu fassen (etwa den Job zu kündigen); 断然 (duànrán) eher die Schärfe und Endgültigkeit, oft gegenüber anderen. Als Adjektiv steht 断然 in 断然措施 (duànrán cuòshī) „drastische Maßnahmen“.",
    "explanation": "断然 (duànrán) beschreibt eine Handlung, die ohne Zögern und mit voller Entschlossenheit ausgeführt wird: „entschieden, kategorisch, kurzerhand“. Typisch steht es vor 拒绝 (jùjué) „ablehnen“, 否认 (fǒurèn) „bestreiten“ oder 采取措施 (cǎiqǔ cuòshī) „Maßnahmen ergreifen“. Vor einer Verneinung (断然不能, 断然不会) verstärkt es diese zu „auf keinen Fall, keinesfalls“; dieser Gebrauch ist besonders schriftlich. Insgesamt ist das Wort gehoben; im Alltag sagt man eher 坚决 (jiānjué) oder 绝对 (juéduì). Es passt zu einmaligen, klaren Entscheidungen, nicht zu Dauerzuständen.",
