    "explanation": "Diese Adverbien verneinen mit einer bestimmten Färbung (Zweifel, Nachdruck, fehlende Möglichkeit, fehlende Notwendigkeit, Verbot).\n不见得 (bújiàndé) – „nicht unbedingt“; zweifelnde, abschwächende Verneinung, eher gesprochen.\n绝不 (juébù) – „keinesfalls, niemals“; starke Verneinung, oft eines Willens oder Versprechens.\n无从 (wúcóng) – „keine Möglichkeit / keinen Ansatzpunkt haben, um …“.\n无须 (wúxū) – „nicht nötig, braucht nicht“ = gehobenes 不必 (búbì).\n无可 (wúkě) – „nichts zu …, nicht können“; fast nur in festen Wendungen wie 无可奉告 (wúkě fènggào) „kein Kommentar“ oder 无可奈何 (wúkě nàihé) „machtlos sein“.\n勿 (wù) – schriftlich „nicht!“ in Verboten und Bitten = 不要 (búyào)/别: 请勿吸烟 (qǐng wù xīyān) „Bitte nicht rauchen“.",
