    "notes": "难怪 (nánguài) ist als Adverb austauschbar und klingt etwas neutraler. Nur 难怪 kann allein als Prädikat stehen: 这也难怪 (zhè yě nánguài) „Das ist verständlich“; 怪不得 (guàibude) braucht dort ein Objekt (这也怪不得他).",
    "explanation": "怪不得 (guàibude) drückt aus, dass man den Grund für etwas Auffälliges plötzlich versteht: „kein Wunder, dass …“, „deshalb also!“. Der Grund steht entweder davor oder folgt oft mit 原来 (yuánlái) „es ist nämlich so, dass …“. Die Wendung ist lebhaft und eher gesprochen; sie kann auch allein als Ausruf stehen („Kein Wunder!“). Als Adverb ist sie bedeutungsgleich mit 难怪 (nánguài). Als Verb heißt 怪不得 außerdem „jemandem nichts vorwerfen können“ und hat dann ein Objekt: 这怪不得他 „Dafür kann er nichts.“ – dieser Gebrauch gehört nicht zum Adverb.",
