    "explanation": "莫非 (mòfēi) leitet eine Vermutung ein, die der Sprecher aus einer auffälligen Beobachtung ableitet, oft mit Verwunderung oder leiser Besorgnis: „sollte etwa …?, ob vielleicht …?“. Der Satz endet meist mit einem Fragezeichen; verstärkend kann 不成 (bùchéng) am Ende stehen (莫非……不成？). Anders als bei 难道 (nándào), das meist eine vorwurfsvolle rhetorische Frage einleitet, hält man bei 莫非 die Vermutung durchaus für möglich oder wahrscheinlich. 莫非 ist gehoben bzw. literarisch; im Alltag sagt man eher 是不是 (shì bu shì) oder 难道.",
    "notes": "难道 (nándào) … 吗 ist meist rhetorisch („soll das etwa heißen …?“, erwartet „nein“), 莫非 (mòfēi) eher eine echte Vermutung („könnte es sein, dass …?“). Die Grenzen sind fließend.",
