    "meaning": "rhetorisch „wann je …?“: mit Verneinung = sehr wohl, ohne = keineswegs",
    "pinyin": "hécháng",
    "formation": "何尝 + (不/没) + Verb (rhetorische Frage oder Aussage)",
    "explanation": "何尝 (hécháng), wörtlich „wann je?“, bildet eine rhetorische Verneinung oder Bejahung. Ohne Verneinung bestreitet es etwas: „Wann hätte ich das je gesagt?“ = „Das habe ich nie gesagt.“ Mit 不 oder 没 bejaht es nachdrücklich: 我何尝不想去 „Als ob ich nicht hingehen wollte!“ = „Natürlich möchte ich.“ Oft folgt ein Satzteil mit 只是 (zhǐshì) oder 可是 (kěshì), der erklärt, warum es trotzdem nicht geht. Der Satz kann mit Fragezeichen oder als Aussage mit Punkt stehen. 何尝 ist gehoben bzw. literarisch; im Alltag sagt man eher 哪里 (nǎli) oder 难道 (nándào) … 吗.",
    "notes": "何尝不是 (hécháng bú shì) „ist das nicht auch …“ ist eine häufige Formel, um einer Sache eine andere, oft positive Seite abzugewinnen. 难道 (nándào) leitet ebenfalls rhetorische Fragen ein, ist aber neutraler und braucht meist 吗.",
