    "notes": "何不 (hébù) „warum nicht …?“ drückt denselben Vorschlag als rhetorische Frage aus: 你何不试试？ Dagegen fragt 何必 (hébì) „wozu denn …?“ und rät gerade ab. 不妨 (bùfáng) ist zurückhaltender als 应该 (yīnggāi), das eine Pflicht nennt.",
