    "notes": "干脆 (gāncuì) ist weitgehend austauschbar, kann aber auch Adjektiv sein („geradeheraus“: 他说话很干脆). 只好 (zhǐhǎo) drückt dagegen ein widerwilliges „notgedrungen“ aus, 索性 (suǒxìng) einen bewussten Entschluss.",
    "explanation": "索性 (suǒxìng) – „kurzerhand, dann eben gleich, einfach“: Weil eine Lage festgefahren ist oder halbe Lösungen nichts bringen, entschließt sich jemand zu einem entschiedenen, oft weitergehenden Schritt. Meist schildert der erste Teilsatz den Anlass (der Regen hört nicht auf, man ist ohnehin zu spät), der zweite mit 索性 die Entscheidung. 索性 steht nach dem Subjekt vor dem Verb und kann Vergangenes berichten oder einen Vorschlag machen: 我们索性……吧. Es ist ein Adverb, keine Konjunktion, verbindet die Teilsätze also nicht selbst. Der Ton ist neutral bis leicht umgangssprachlich; das Synonym 干脆 (gāncuì) ist noch alltäglicher.",
