    "notes": "千万 (qiānwàn) aus HSK 4 ist das alltägliche Gegenstück für Bitten und Warnungen. 万万没想到 (wànwàn méi xiǎngdào) ist eine feste Wendung für große Überraschung; vgl. auch 竟然 (jìngrán) „wider Erwarten“.",
    "explanation": "万万 (wànwàn) verstärkt eine Verneinung aufs Äußerste und steht nur vor 不 oder 没(有): „auf keinen Fall, keinesfalls“. Zwei typische Verwendungen: 万万 + 不能 (bù néng) / 不可 (bù kě) / 不要 (bú yào) + Verb ist eine eindringliche Warnung oder ein Verbot („das darfst du auf keinen Fall …“); 万万没(有)想到 (xiǎngdào) drückt aus, dass etwas völlig unerwartet kam („nie im Leben hätte ich gedacht, dass …“). Ohne Verneinung ist 万万 nicht möglich. Es klingt nachdrücklicher und etwas gehobener als 千万 (qiānwàn); 千万 kann auch bejahend stehen (千万要小心, „pass bloß auf“), 万万 nicht.",
