    "formation": "Subjekt + 乃 + Nomen(gruppe)",
    "notes": "Andere klassische Bedeutungen von 乃 – „erst dann, daraufhin“ (≈ 才 oder 于是 (yúshì)) oder „du, dein“ – kommen in modernen Texten fast nur in festen Wendungen vor. 乃至 (nǎizhì) „bis hin zu“ ist eine eigene Konjunktion.",
    "explanation": "乃 (nǎi) ist ein schriftsprachliches, aus dem klassischen Chinesisch stammendes Urteilswort mit der Bedeutung „ist, ist nämlich“ (≈ 是 oder 就是 (jiùshì)). Es verbindet ein Subjekt mit einer Einordnung oder Bewertung und gibt dem Satz einen feierlichen, sentenzhaften Ton. Typisch sind Sprichwörter und Merksätze, Festreden und offizielle Texte, oft zusammen mit anderen klassischen Elementen wie 此 (cǐ) „dies“ und 之 (zhī) als Attributpartikel. In der Alltagssprache wirkt 乃 gestelzt oder scherzhaft; dort sagt man 是. 乃 wird nicht verneint – verneint wird mit 并非 (bìngfēi) oder 不是 (bú shì).",
