    "meaning": "von … an, ab, aus (Ausgangspunkt in Zeit und Ort, gesprochen)",
    "formation": "打 + Zeit/Ort (+ 起/开始) + Verb",
    "notes": "打 ist außerdem Zählwort „Dutzend“ (一打鸡蛋, yì dá jīdàn – eigener Punkt, HSK 4) und vor allem ein vielseitiges Verb. Die Wendung 打个比方 (dǎ ge bǐfang) „zum Vergleich“ ist ein eigener Punkt. Gehobene Entsprechungen sind 自 (zì) und für Zeitpunkte in der Vergangenheit 自从 (zìcóng).",
    "explanation": "Als Präposition entspricht 打 (dǎ) weitgehend 从 (cóng) „von, ab, aus“, ist aber deutlich umgangssprachlich und besonders in Nordchina verbreitet. Es nennt (1) den Beginn eines Zeitraums, meist mit 起 (qǐ) oder 开始 (kāishǐ) danach: 打明天起 „ab morgen“; (2) den Ausgangsort einer Bewegung: 你打哪儿来？ „Woher kommst du?“; (3) den Weg, über den eine Bewegung führt: 打这条路走 „diesen Weg nehmen“. Feste Wendung: 打小 (dǎxiǎo) „von klein auf“. In formellen Texten steht stattdessen 从 oder 自 (zì). Nicht verwechseln mit dem Verb 打 („schlagen, spielen, anrufen“: 打电话 (dǎ diànhuà)) – die Präposition steht vor einer Zeit- oder Ortsangabe, auf die noch ein Verb folgt.",
