    "notes": "当 (dāng) ohne 着 leitet einen Zeitpunkt ein (当……的时候 „als, während“). Das Adverb 当面 (dāngmiàn) heißt „von Angesicht zu Angesicht, direkt“: 有话当面说 (yǒu huà dāngmiàn shuō) „Sag es mir ins Gesicht“.",
    "explanation": "当着 (dāngzhe) nennt die Person oder Gruppe, vor deren Augen etwas geschieht: „vor jemandem, in jemandes Anwesenheit“. Oft folgt 的面 (de miàn), wörtlich „das Gesicht“: 当着大家的面 „vor allen“. Die Fügung steht vor dem Verb und betont, dass die Anwesenden etwas direkt mitbekommen – häufig mit dem Unterton, dass es dadurch peinlich, mutig oder bewusst öffentlich ist (sich vor allen entschuldigen, vor den Kindern streiten). 当着 verbindet sich mit Personen, nicht mit Orten oder Dingen. Gleichbedeutend, aber alltäglicher ist 在 + Person + 面前 (miànqián). Nicht verwechseln mit 对着 (duìzhe) „zu jemandem hin, auf jemanden gerichtet“.",
