    "explanation": "Als Präposition nennt 鉴于 (jiànyú) einen Umstand, der bei einer Entscheidung berücksichtigt wird: „angesichts, in Anbetracht“. Die Präpositionalgruppe steht fast immer am Satzanfang, durch ein Komma abgetrennt; der Hauptsatz nennt eine Entscheidung, Maßnahme oder Folgerung wie 决定 (juédìng), 推迟 (tuīchí) oder 取消 (qǔxiāo). Der Stil ist formell – typisch für Bekanntmachungen, Berichte und Begründungen. Häufig ist 鉴于此 (jiànyú cǐ) bzw. 有鉴于此 (yǒu jiànyú cǐ) „in Anbetracht dessen“, das auf den vorigen Satz zurückverweist. Für einen einfachen Grund im Alltag sagt man eher 因为 (yīnwèi) oder 由于 (yóuyú).",
