    "explanation": "基于 (jīyú) nennt die sachliche Grundlage einer Schlussfolgerung, Entscheidung oder Methode: „auf Grundlage von, basierend auf“. Es verbindet sich mit Nomen wie 分析 (fēnxī), 数据 (shùjù), 调查 (diàochá), 考虑 (kǎolǜ) oder 事实 (shìshí). Die Präpositionalgruppe steht entweder am Satzanfang (基于以上分析，……) oder nach 是 als nachgereichte Begründung: 这个决定是基于……做出的. In der Fachsprache steht 基于 auch in Attributen vor einem Nomen: 基于网络的教学 „webbasierter Unterricht“. Der Ton ist schriftsprachlich; im Alltag sagt man 根据 (gēnjù).",
