    "formation": "经 (+ Person/Stelle) + Verb (批准/同意/讨论/检查)，Ergebnis",
    "notes": "Anders als das Passiv mit 被 (bèi) nennt 经 eine Voraussetzung, keinen Täter. 由 (yóu) legt dagegen fest, wer eine Aufgabe übernimmt: 由医生决定 „das entscheidet der Arzt“.",
    "explanation": "Die Präposition 经 (jīng) nennt ein Verfahren, das eine Sache durchlaufen hat, bevor das Ergebnis im Hauptsatz eintritt: „nach, durch, mit (Genehmigung)“. Auf 经 folgt ein Verb wie 批准 (pīzhǔn), 同意 (tóngyì), 研究 (yánjiū), 讨论 (tǎolùn) oder 检查 (jiǎnchá), oft mit der handelnden Person oder Stelle davor: 经上级批准 „mit Genehmigung der Vorgesetzten“, 经医生检查 „nach ärztlicher Untersuchung“. Die Gruppe steht meist am Satzanfang oder nach dem Subjekt vor dem Hauptverb. Der Stil ist knapp und formell (Bekanntmachungen, Nachrichten); 经过 (jīngguò) ist die längere, auch gesprochene Form. Mit 已经 (yǐjīng) oder 经常 (jīngcháng) hat diese Präposition nichts zu tun.",
