    "formation": "Handlung/Rat，免得 + unerwünschte Folge",
    "notes": "Gegenstück für einen erwünschten Zweck ist 以便 (yǐbiàn) „damit, um zu“ (HSK 6). 以防 (yǐfáng) ist ähnlich, betont aber Vorsorge gegen eine Gefahr oder einen Notfall.",
    "explanation": "免得 (miǎnde) leitet den zweiten Teilsatz ein und nennt eine unerwünschte Folge, die durch die Handlung im ersten Teilsatz vermieden werden soll: „damit nicht, sonst“. Der erste Teil ist oft ein Rat oder eine Aufforderung, der zweite beschreibt, was dann nicht passieren soll – nach 免得 steht deshalb das Unerwünschte selbst, ohne zusätzliche Verneinung: 免得忘了 „damit man es nicht vergisst“. 免得 steht nicht vor dem ersten Teilsatz. Es ist eher gesprochen; 以免 (yǐmiǎn) ist die schriftsprachliche, 省得 (shěngde) die noch umgangssprachlichere Entsprechung.",
