    "formation": "A、B 乃至 C；Teilsatz A，乃至 Teilsatz B",
    "explanation": "乃至 (nǎizhì) führt eine Reihe bis zu ihrem größten, weitesten oder überraschendsten Glied fort: „bis hin zu, ja sogar“. Meist verbindet es Nomen oder Nominalgruppen, die vom Kleinen zum Großen geordnet sind – etwa vom Einzelnen über die Familie bis zur ganzen Gesellschaft; seltener verbindet es Teilsätze. Danach steht häufig 都 (dōu) oder ein Wort wie 整个 (zhěnggè) bzw. 全 (quán). Der Ausdruck ist schriftsprachlich und typisch für Nachrichten, Reden und Fachtexte; die Form 乃至于 (nǎizhìyú) ist gleichbedeutend. Im Alltag sagt man eher 甚至 (shènzhì).",
    "notes": "甚至 (shènzhì) ist gebräuchlicher und kann auch als Adverb direkt vor einem Verb stehen. 以至 (yǐzhì) bzw. 以至于 (yǐzhìyú) nennt dagegen meist eine Folge („sodass“). 乃 (nǎi) allein ist ein schriftsprachliches „ist“.",
