    "explanation": "Als Konjunktion bedeutet 且 (qiě) „und (zugleich), zudem“ und ist die knappe schriftsprachliche Entsprechung von 而且 (érqiě) bzw. 并且 (bìngqiě). Es verbindet vor allem zwei Adjektive oder Verben, die gleichzeitig zutreffen (简单且有效 „einfach und wirksam“), steht in der festen Form 既……且…… „sowohl … als auch“ oder leitet einen zweiten Teilsatz ein, der etwas Weiterführendes hinzufügt. Zwei Nomen verbindet 且 normalerweise nicht – dafür stehen 和 (hé) oder 与 (yǔ). Im Gespräch wirkt 且 steif; dort sagt man eher 又……又…… oder 而且.",
