    "meaning": "Modalpartikeln der gehobenen Sprache: „nur, weiter nichts“, „na gut“, klassisches Satzende",
    "notes": "罢了 (bàle) ist nicht dasselbe wie 也罢 (yěbà): 罢了 verkleinert eine Aussage („nur“), 也罢 nimmt eine Lage hin („na gut“). Das Muster 无非 (wúfēi)/不过 (búguò)/只是 (zhǐshì) … 罢了 ist ein eigener Punkt.",
    "explanation": "Auf dieser Stufe kommen drei Satzpartikeln hinzu, die vor allem in gehobener Sprache und in festen Wendungen vorkommen:\n罢了 (bàle) – am Satzende: „nur, weiter nichts“; spielt etwas herunter, meist zusammen mit 不过 (búguò), 只是 (zhǐshì) oder 无非 (wúfēi): 我只是随便问问罢了 „ich frage ja nur so“. Gesprochen wie geschrieben üblich, gleichbedeutend mit 而已 (éryǐ).\n也罢 (yěbà) – „na gut, sei's drum“: frei stehend oder nach einem Satzteil zeigt es, dass man sich mit etwas abfindet; doppelt gesetzt (X也罢，Y也罢) heißt es „ob X oder Y – gleichgültig“.\n矣 (yǐ) – klassische Partikel, entspricht etwa 了 am Satzende (Abschluss, neue Lage). Heute nur in festen, gehobenen Wendungen: 足矣 (zú yǐ) „das genügt“, 悔之晚矣 (huǐ zhī wǎn yǐ) „zu spät für Reue“, 久矣 (jiǔ yǐ) „seit Langem“. In normaler Rede wirkt 矣 gestelzt oder scherzhaft.",
