    "explanation": "也罢 (yěbà) ist eine Modalpartikel des Sich-Abfindens: Der Sprecher nimmt eine Lage hin, die ihm nicht ganz recht ist, und zieht daraus seine Folgerung – „na gut“, „sei's drum“, „dann eben“. Es steht frei am Satzanfang (也罢，你去吧 „na gut, dann geh“) oder hinter einem Satzteil, der das Hingenommene nennt (他不来也罢 „wenn er nicht kommt, auch gut“). Zweimal gesetzt, X也罢，Y也罢, heißt es „ob X oder Y“: Beide Möglichkeiten ändern nichts am Ergebnis, das dann meist mit 都 (dōu) oder 也 (yě) folgt. 也罢 klingt etwas gehobener und resignierter als das gesprochene 算了 (suànle) oder 也好 (yěhǎo).",
