    "notes": "Nicht verwechseln mit der Frage A不A (去不去 „gehst du?“): Erst das vorangestellte 爱 macht daraus eine abweisende Feststellung. Milder klingt 也罢 (yěbà): 不去也罢 „dann eben nicht“.",
    "explanation": "Im Muster 爱A不A steht zweimal dasselbe Verb, einmal nach 爱 („gern mögen“), einmal nach 不: 爱去不去 (ài qù bú qù) heißt wörtlich „wenn du gehen magst, geh, wenn nicht, dann nicht“. Gemeint ist: „Das ist deine Sache, mir ist es egal.“ Der Sprecher überlässt dem anderen die Entscheidung, aber unwillig, gereizt oder abschätzig – oft nach einem Streit oder einer abgelehnten Bitte. Typisch sind kurze, einsilbige Verben: 爱信不信 (ài xìn bú xìn), 爱吃不吃 (ài chī bù chī), 爱来不来 (ài lái bù lái). Das Muster ist rein umgangssprachlich und steht meist am Satzende; oft kommt 反正 (fǎnzhèng) „sowieso“ oder 随便你 (suíbiàn nǐ) „wie du willst“ hinzu. Gegenüber Höhergestellten oder in höflicher Rede wirkt es grob.",
