    "explanation": "Im Muster 半A半B stehen zwei meist gegensätzliche Wörter, jedes nach 半 (bàn) „halb“. Es beschreibt einen Zustand dazwischen: Beides trifft teilweise zu, keines ganz. Feste Ausdrücke sind 半信半疑 (bànxìn-bànyí) „halb glauben, halb zweifeln“, 半真半假 (bànzhēn-bànjiǎ) „halb wahr, halb erfunden“, 半推半就 (bàntuī-bànjiù) „sich zierend nachgeben“ und 半工半读 (bàngōng-bàndú) „neben dem Studium arbeiten“. Frei gebildet werden Verbindungen wie 半睡半醒 (bàn shuì bàn xǐng) „im Halbschlaf“ oder 半开玩笑半认真 (bàn kāi wánxiào bàn rènzhēn) „halb im Scherz, halb im Ernst“. Die Wendungen stehen als Prädikat, mit 地 (de) als Adverbial oder mit 的 (de) als Attribut; sie klingen eher schriftlich, die festen Ausdrücke sind aber auch im Gespräch üblich.",
