    "notes": "Vom HSK-3-Muster (不冷不热 (bù lěng bú rè) „angenehm temperiert“) unterscheidet sich dieser Punkt durch die Bedeutung: dort Lob der Mitte, hier verstärkte Verneinung, Abwertung oder Bedingung. Verwandt sind 无A无B (无忧无虑 (wúyōu-wúlǜ) „sorglos“) und 非A非B.",
    "explanation": "Auf HSK-3-Stufe verbindet 不A不B zwei gegensätzliche Adjektive zu „genau richtig“ (不大不小). Hier geht es um feste, eher schriftsprachliche Vierwortausdrücke mit drei Lesarten: 1. A und B sind sinnverwandt, das doppelte 不 verstärkt die Verneinung: 不慌不忙 (bùhuāng-bùmáng) „ganz gelassen“, 不闻不问 (bùwén-búwèn) „sich um nichts kümmern“, 不声不响 (bùshēng-bùxiǎng) „still, ohne Aufhebens“, 不知不觉 (bùzhī-bùjué) „unmerklich“. 2. Weder das eine noch das andere, also etwas Unpassendes oder Zwielichtiges, abwertend: 不三不四 (bùsān-búsì) „zwielichtig“, 不伦不类 (bùlún-búlèi) „weder Fisch noch Fleisch“. 3. Bedingung „wenn nicht A, dann nicht B“: 不见不散 (bújiàn-búsàn) „wir warten aufeinander, bis wir uns treffen“. Die Ausdrücke stehen als Adverbial mit 地 (de), als Prädikat oder als Attribut; die meisten sind fest, frei gebildet wird etwa 不吃不喝 (bù chī bù hē) „weder essen noch trinken“.",
