    "notes": "时A时B (时好时坏 (shí hǎo shí huài)) beschreibt ebenfalls einen Wechsel, betont aber das wiederholte Auftreten über längere Zeit, 忽A忽B dagegen das Plötzliche. Im Gespräch sagt man auch 一会儿 (yíhuìr) A，一会儿 B.",
    "explanation": "忽 (hū) heißt „plötzlich“. In 忽A忽B stehen zwei Gegensätze, und das Muster beschreibt einen raschen, unvorhersehbaren Wechsel zwischen ihnen: 忽冷忽热 (hū lěng hū rè) „mal kalt, mal heiß“, 忽高忽低 (hū gāo hū dī) „mal hoch, mal tief“, 忽明忽暗 (hū míng hū àn) „mal hell, mal dunkel“ (flackerndes Licht), 忽快忽慢 (hū kuài hū màn) „mal schnell, mal langsam“, 忽大忽小 (hū dà hū xiǎo). Oft schwingt mit, dass der Wechsel stört oder unberechenbar ist. Übertragen beschreibt 忽冷忽热 auch launisches Verhalten: 她对我忽冷忽热 „sie ist mal herzlich, mal abweisend zu mir“. Das Muster ist eher schriftlich, aber auch im Gespräch geläufig; es steht meist als Prädikat, seltener mit 地 (de) als Adverbial.",
