    "notes": "Die Lesart „A oder nicht A“ bildet man auch mit Verb und Verneinung: 可去可不去 (kě qù kě bú qù) „man kann hingehen oder es lassen“. Gegenstück ist 无A可B (无话可说 (wúhuà-kěshuō) „nichts zu sagen haben“), wo eine Möglichkeit verneint wird.",
    "explanation": "可 (kě) bedeutet hier „können, dürfen“ oder „wert sein“. Das Muster hat zwei Lesarten: 1. A und B sind Gegensätze: Beides ist möglich oder zulässig, je nach Umständen – 可长可短 (kě cháng kě duǎn) „kann länger oder kürzer sein“, 可多可少 (kě duō kě shǎo) „mehr oder weniger, je nachdem“, 可大可小 (kě dà kě xiǎo) „kann harmlos bleiben, aber auch ernst werden“. Besonders häufig ist 可有可无 (kěyǒu-kěwú) „entbehrlich, unwichtig“. 2. A und B sind sinnverwandte Verben: „verdient es, dass man A und B tut“ – 可歌可泣 (kěgē-kěqì) „ergreifend, heldenhaft“, 可喜可贺 (kěxǐ-kěhè) „erfreulich, ein Grund zum Feiern“, 可圈可点 (kěquān-kědiǎn) „bemerkenswert, lobenswert“. Das Muster ist schriftsprachlich; im Gespräch kommen vor allem 可有可无 und 可大可小 vor. Es bedeutet nicht „mal A, mal B“ – das wäre 时A时B oder 忽A忽B.",
