    "explanation": "Die Zahlen 七 (qī) „sieben“ und 八 (bā) „acht“ stehen in diesem Muster für „viel, vielerlei“ und zugleich für Durcheinander. Eingesetzt werden zwei zusammengehörige Wörter, meist Nomen oder Verben: 七嘴八舌 (qīzuǐ-bāshé) „alle reden durcheinander“, 七手八脚 (qīshǒu-bājiǎo) „viele packen hastig mit an“, 七上八下 (qīshàng-bāxià) „innerlich aufgewühlt, nervös“, 七拼八凑 (qīpīn-bācòu) „notdürftig zusammengestückelt“, 七零八落 (qīlíng-bāluò) „verstreut, in Unordnung“. Die Ausdrücke klingen lebendig und eher umgangssprachlich; meist beschreiben sie etwas Ungeordnetes oder Hektisches und sind oft leicht abwertend. Sie stehen als Prädikat, mit 地 (de) als Adverbial oder mit 的 (de) als Attribut. 七上八下 bezieht sich fast immer auf 心里 (xīnli) „im Innern“.",
