    "notes": "忽A忽B (忽冷忽热 (hū lěng hū rè)) betont das Plötzliche und Schnelle des Wechsels, 时A时B die Wiederholung über längere Zeit. Gesprochen sagt man auch 一会儿 (yíhuìr) A，一会儿 B.",
    "explanation": "时 (shí) steht hier für „zeitweise“: 时A时B beschreibt einen Zustand, der über längere Zeit immer wieder zwischen zwei Gegensätzen wechselt – „mal A, mal B“, „bald A, bald B“. Häufig sind 时好时坏 (shí hǎo shí huài) „mal besser, mal schlechter“, 时有时无 (shí yǒu shí wú) „mal da, mal weg“, 时高时低 (shí gāo shí dī) „mal hoch, mal tief“, 时断时续 (shíduàn-shíxù) „mit Unterbrechungen“, 时隐时现 (shíyǐn-shíxiàn) „mal sichtbar, mal verborgen“. Die Bewertung ist meist negativ: Etwas ist unbeständig oder unzuverlässig. Das Muster ist schriftlich geprägt, im Gespräch aber durchaus üblich; es steht als Prädikat oder mit 地 (de) als Adverbial. Für längere Glieder gibt es 时而 (shí'ér) A，时而 B.",
