    "notes": "Nicht verwechseln mit 无A无B (无忧无虑 (wúyōu-wúlǜ) „sorglos“), das „ganz ohne“ bedeutet, und mit 无A可B (无话可说 (wúhuà-kěshuō) „nichts zu sagen haben“). Vergleiche: 无话不谈 (wúhuà-bùtán) „über alles reden“ – 无话可说 „nichts mehr zu sagen“.",
    "explanation": "无A不B ist eine doppelte Verneinung: „Es gibt kein A, das nicht B ist oder tut“ – also „jedes A ist B“, „ausnahmslos“. Das Ergebnis ist eine nachdrückliche Bejahung. Feste Ausdrücke: 无话不谈 (wúhuà-bùtán) „über alles reden können“ (sehr enge Freundschaft), 无微不至 (wúwēi-búzhì) „bis ins Kleinste fürsorglich“, 无奇不有 (wúqí-bùyǒu) „es gibt alles Erdenkliche“, 无所不知 (wúsuǒ-bùzhī) „allwissend“, 无所不能 (wúsuǒ-bùnéng) „alles können“, 无恶不作 (wú'è-búzuò) „vor keiner Untat zurückschrecken“, 无孔不入 (wúkǒng-búrù) „jede Lücke nutzen, überall eindringen“. Das Teilmuster mit 所 (suǒ) ist am produktivsten. Die Ausdrücke gehören zur Schriftsprache, 无话不谈 und 无微不至 sind auch im Gespräch häufig. Ironisch kann 无所不知 Überheblichkeit ausdrücken.",
