    "notes": "无A不B (无话不谈 (wúhuà-bùtán) „über alles reden“) bejaht nachdrücklich, 无A可B verneint eine Möglichkeit. In 无可奈何 (wúkěnàihé) „machtlos“ fehlt das Nomen A; es gehört nicht zu diesem Muster.",
    "explanation": "In 无A可B ist A ein Nomen, B ein Verb, dessen Objekt A ist: „Es gibt kein A, das man B-en könnte.“ 无话可说 (wúhuà-kěshuō) heißt also „es gibt nichts, was man sagen könnte“ – „nichts (mehr) zu sagen haben, sprachlos sein“. Weitere häufige Ausdrücke: 无家可归 (wújiā-kěguī) „obdachlos“, 无路可走 (wúlù-kězǒu) „keinen Ausweg haben“, 无事可做 (wú shì kě zuò) „nichts zu tun haben“, 无计可施 (wújì-kěshī) „mit seinem Latein am Ende“, 无懈可击 (wúxiè-kějī) „makellos, unangreifbar“, 无药可救 (wúyào-kějiù) „hoffnungslos“. Das Muster ist schriftsprachlich, lässt sich aber auch frei bilden: 无处可去 (wú chù kě qù) „nirgendwohin gehen können“. Modern sagt man dafür 没有 (méiyǒu) A 可以 (kěyǐ) B.",
