    "formation": "自 + A + 自 + B (A, B: einsilbige Verben oder Adjektive)",
    "notes": "Nicht verwechseln mit dem Reflexivpronomen 自己 (zìjǐ) „selbst“: In 自A自B wird 自 vor jedem der beiden Wörter wiederholt, die Vierergruppe ist fest. 自作自受 (zìzuò-zìshòu) tadelt jemanden, der sein Unglück selbst verschuldet hat.",
    "explanation": "自 (zì) bedeutet „selbst, von sich aus“. In 自A自B steht es vor zwei sinnverwandten oder aufeinander bezogenen Wörtern: Die Handlung geht vom Handelnden aus und betrifft ihn selbst, ohne andere. Häufig sind 自言自语 (zìyán-zìyǔ) „Selbstgespräche führen“, 自给自足 (zìjǐ-zìzú) „sich selbst versorgen“, 自作自受 (zìzuò-zìshòu) „selbst schuld sein, die Folgen selbst tragen“, 自私自利 (zìsī-zìlì) „selbstsüchtig“, 自高自大 (zìgāo-zìdà) „überheblich“, 自娱自乐 (zìyú-zìlè) „sich selbst unterhalten“. Frei gebildet wird etwa 自编自导 (zì biān zì dǎo) „selbst schreiben und Regie führen“ oder 自问自答 (zìwèn-zìdá) „sich selbst fragen und antworten“. Eigenschaftsausdrücke wie 自私自利 und 自高自大 sind abwertend. Das Muster ist schriftlich geprägt, die häufigen Ausdrücke sind aber auch im Gespräch geläufig.",
