    "notes": "Gegenstück zu 不瞒你说 (bù mán nǐ shuō), das ein Geständnis über einen selbst einleitet. Ähnlich, aber direkter ist 说句不好听的 (shuō jù bù hǎotīng de) „um es mal unverblümt zu sagen“.",
    "explanation": "不是我说你 (bú shì wǒ shuō nǐ) heißt wörtlich „nicht dass ich dich tadeln will“ – und leitet genau das ein: eine Kritik, einen Vorwurf oder einen gut gemeinten Rat an den Gesprächspartner. Die Wendung soll den Tadel abfedern und zeigt zugleich, dass der Sprecher ihn für berechtigt hält, etwa „nimm's mir nicht übel, aber …“, „ich muss es dir mal sagen“. Sie steht am Satzanfang, oft mit 啊 (a) oder 呀 (ya) verlängert, und ist rein umgangssprachlich. Üblich ist sie unter Vertrauten oder von Älteren gegenüber Jüngeren; gegenüber Vorgesetzten wirkt sie respektlos. Die Person kann wechseln: 不是我说他 (bú shì wǒ shuō tā) für Kritik an einem Dritten. 说 (shuō) bedeutet hier „tadeln, ermahnen“, nicht „sagen“.",
