    "formation": "Aussage A，(但)反过来（说），+ umgekehrte Sicht auf A",
    "notes": "Nicht verwechseln mit 换句话说 (huàn jù huà shuō), das dasselbe nur anders formuliert, und mit 话说回来 (huà shuō huílai), das einen anderen Aspekt einwendet, ohne das Verhältnis umzudrehen. Wörtlich heißt 反过来 (fǎnguòlái) auch „umdrehen, wenden“: 把衣服反过来 (bǎ yīfu fǎnguòlái) „die Kleidung auf links drehen“.",
    "explanation": "反过来说 (fǎnguòlái shuō) leitet die Umkehrung des eben Gesagten ein: Nach einer Aussage über A und B betrachtet der Sprecher dasselbe Verhältnis aus der Gegenrichtung („umgekehrt gilt auch …“). Oft geht es um Wechselwirkungen („die Umwelt prägt den Menschen – umgekehrt prägt der Mensch die Umwelt“) oder um den Umkehrschluss („Fleiß garantiert keinen Erfolg – umgekehrt: ohne Fleiß sicher keiner“). 说 kann wegfallen; 反过来 (fǎnguòlái) steht dann auch mitten im Satz vor dem Verb („孩子反过来也该关心父母“). Gesprochen und geschrieben gleichermaßen üblich. Der Marker setzt immer eine vorangehende Aussage voraus, am Textanfang ist er falsch.",
