    "notes": "Abgrenzung: 简而言之 (jiǎn'ér yánzhī) betont die Kürze („kurz gesagt“), 综上所述 (zōngshàng suǒ shù) zieht schriftsprachlich das Fazit am Ende einer Argumentation, 归根到底 (guīgēn dàodǐ) nennt den eigentlichen Kern oder Grund.",
    "explanation": "概括来说 (gàikuò lái shuō) kündigt an, dass der Sprecher einen umfangreicheren Inhalt auf seine Hauptpunkte bringt: „zusammengefasst“, „grob gesagt“, „im Überblick“. 概括 (gàikuò) heißt „zusammenfassen, verallgemeinern“; 来说 (lái shuō) macht daraus einen Satzeinleiter wie in 一般来说 (yìbān lái shuō) „im Allgemeinen“. Typisch in Präsentationen, Berichten, Buch- oder Filmbeschreibungen. Der Marker kann am Anfang stehen oder nach einer Einleitung („会议讨论了很多问题，概括来说……“). Gleichbedeutend sind 概括地说 (gàikuò de shuō) und 总的来说 (zǒng de lái shuō). Es folgt eine knappe Zusammenfassung, keine neuen Details.",
