    "explanation": "简而言之 (jiǎn'ér yánzhī) oder kürzer 简言之 (jiǎn yán zhī), wörtlich „es knapp sagen“, bringt einen längeren Gedankengang auf eine einzige, knappe Aussage: „kurz gesagt“, „kurzum“, „um es kurz zu machen“. Der Ausdruck stammt aus der klassischen Schriftsprache (而 ér verbindet, 之 zhī ist Objektpronomen) und klingt deshalb gehoben; er ist typisch für Vorträge, Berichte und Aufsätze, im lockeren Gespräch sagt man eher 简单地说 (jiǎndān de shuō) oder 总之 (zǒngzhī). Die folgende Aussage sollte wirklich kurz sein; eine lange Aufzählung passt nicht dazu.",
