    "notes": "Nicht verwechseln mit 这不 (zhè bù), das ein aktuelles Beispiel für das Gesagte vorführt („da, siehst du!“). 可 kann auch als Gradadverb Aussagen verstärken (可好了 (kě hǎo le) „richtig gut“); hier ist es Teil der festen Zustimmungsformel.",
    "explanation": "可不是嘛 (kě bú shì ma), kurz 可不 (kěbù) oder 可不是 (kě bú shì), ist eine rhetorische Frage („ist es etwa nicht so?“) und bedeutet daher volle Zustimmung: „Genau!“, „Eben!“, „Allerdings!“, „Da sagst du was!“. Man reagiert damit auf die Aussage eines Gesprächspartners und bestätigt sie meist mit einem eigenen Beispiel oder Gefühl. Statt 嘛 (ma) steht oft auch 吗 (ma). Rein gesprochen und eher locker. Wichtig: Trotz 不 drückt der Ausdruck keine Verneinung aus; wer widersprechen will, braucht etwas anderes, z. B. 话是这么说 (huà shì zhème shuō) oder 说到哪儿去了 (shuōdào nǎr qù le).",
