    "notes": "Achtung: 你老实说 (nǐ lǎoshi shuō) ist dagegen eine Aufforderung an den anderen („sag die Wahrheit!“), kein Diskursmarker des Sprechers.",
    "explanation": "老实说 (lǎoshi shuō), von 老实 (lǎoshi) „ehrlich, aufrichtig“, kündigt an, dass der Sprecher offen seine wirkliche Meinung oder ein Geständnis äußert: „ehrlich gesagt“, „offen gestanden“. Oft ist das Folgende etwas unbequem – Kritik, Unzufriedenheit, ein Zugeben von Schwäche – und der Marker mildert es ab. Er steht am Satzanfang oder nach einer Einleitung, gern nach 但 (dàn) oder 可 (kě): „方案不错，但老实说，……“. Gesprochen und geschrieben gebräuchlich, neutral im Ton. Gleichbedeutend sind 说实话 (shuō shíhuà) und 说真的 (shuō zhēn de); etwas vertraulicher ist 不瞒你说 (bù mán nǐ shuō) „ich will dir nichts vormachen“.",
