    "explanation": "还别说 (hái bié shuō), oft mit 你 davor als 你还别说 (nǐ hái bié shuō), wörtlich „sag noch nichts (dagegen)“, leitet eine Feststellung ein, die den eigenen oder fremden Erwartungen widerspricht – meist angenehm überrascht: „man glaubt es kaum, aber …“, „das muss man sagen“, „tatsächlich“. Häufig folgt im selben Satz 还真 (hái zhēn) oder 还挺 (hái tǐng): „你还别说，这个办法还真管用“. Oft ging Skepsis voraus („ich wollte erst gar nicht …“). Der Ausdruck ist umgangssprachlich, besonders im Norden verbreitet; in formellen Texten wirkt er fehl am Platz. Gemeint ist keine Aufforderung zu schweigen – 别说 (bié shuō) ist hier erstarrt.",
