    "explanation": "说真的 (shuō zhēn de), „ernsthaft gesprochen“, hat zwei eng verwandte Funktionen: (1) Der Sprecher kündigt eine aufrichtige persönliche Meinung oder ein Gefühl an: „ganz ehrlich“, „wirklich“ („说真的，我挺羡慕你的“). (2) Er wechselt vom Scherz oder Smalltalk zu einem ernsten Thema: „im Ernst“, „jetzt mal ernsthaft“. Rein umgangssprachlich; in Texten wirkt es salopp. Gleichbedeutend sind 说实话 (shuō shíhuà) und 老实说 (lǎoshi shuō); für Funktion (2) auch 说正经的 (shuō zhèngjing de).",
