    "explanation": "这样一来 (zhèyàng yìlái), „wenn es so kommt“, verweist auf eine eben genannte Handlung, Maßnahme oder Veränderung und leitet ihre Folge ein: „dadurch“, „auf diese Weise“, „damit“, „so“. Die Folge kann erwünscht sein (Ziel einer Maßnahme) oder unerwünscht (Nebenwirkung): „公司搬到了郊区，这样一来，我上班要花两个小时“. Häufig steht im Folgesatz 就 (jiù). Neutral, in Gespräch und Text gleichermaßen gebräuchlich; umgangssprachliche Variante 这么一来 (zhème yìlái). Anders als 所以 (suǒyǐ) betont 这样一来 weniger eine logische Begründung als die praktische Auswirkung einer konkreten Veränderung.",
