    "explanation": "Mit 得要命 (de yàomìng) oder 得要死 (de yàosǐ) übertreibt man den Grad eines Zustands, wörtlich „so X, dass es einen umbringt“: „todmüde“, „wahnsinnig hungrig“, „furchtbare Angst haben“. X ist ein Adjektiv wie 累 („müde“), 冷 („kalt“), 疼 („schmerzhaft“) oder ein psychisches Verb wie 怕 („fürchten“), 想 („vermissen“), 喜欢 (xǐhuan). Das Muster ist umgangssprachlich und gefühlsbetont; meist geht es um Unangenehmes, aber auch starke positive Gefühle sind möglich, etwa mit 高兴 (gāoxìng) „froh“. In formellen Texten vermeidet man es. 得 (de) ist unverzichtbar, und vor X steht kein Gradadverb wie 很 oder 非常 (fēicháng). Das Muster bildet meist das Satzende.",
