    "explanation": "Zwei Verben werden mit 了 (le) verbunden und gleich danach in umgekehrter Reihenfolge wiederholt: 吃了睡，睡了吃 „essen, schlafen, schlafen, essen“. So entsteht das Bild eines Kreislaufs, in dem sich zwei Handlungen immer wieder abwechseln, ohne dass etwas Neues geschieht. Je nach Zusammenhang klingt das nach Eintönigkeit oder Faulheit (nur essen und schlafen), nach Unentschlossenheit (an- und ausziehen, ohne zu kaufen) oder nach großer Mühe (schreiben und korrigieren, immer wieder). Meist sind X und Y einsilbige Verben, die ein natürliches Paar bilden: 穿 und 脱, 写 und 改, 拆 und 装. 了 bedeutet hier „nachdem X erledigt ist“: Auf X folgt jeweils Y und umgekehrt. Das Muster ist anschaulich und umgangssprachlich; oft folgt ein Satz mit dem enttäuschenden Ergebnis.",
