    "notes": "Allein kann 也好 (yěhǎo) auch „auch gut, umso besser“ bedeuten, 也罢 (yěbà) allein „na gut, meinetwegen“ (eigene Punkte). Bei 不管 (bùguǎn) … 都 … steht die Bedingung als Alternative mit 还是 (háishi); hier werden die Möglichkeiten als Feststellungen gereiht.",
    "explanation": "Mit 也好 (yěhǎo) und 也罢 (yěbà) stellt man zwei Möglichkeiten nebeneinander und sagt, dass das Ergebnis nicht davon abhängt: „ob X oder Y …“, „sei es X, sei es Y“. X und Y sind meist Gegensätze, etwa 成功 (chénggōng) „Erfolg“ und 失败 (shībài) „Misserfolg“, oder Glieder einer Reihe von ähnlicher Länge. Im Folgesatz steht oft 都 (dōu) oder 也 (yě); der Sinn entspricht 无论 (wúlùn) bzw. 不管 (bùguǎn) … 都 …. Die gemischte Form mit 也好 und 也罢 klingt gehoben und abwechslungsreich; die gleichförmigen Varianten „X也好，Y也好“ und „X也罢，Y也罢“ sind ebenso korrekt. Das Muster drückt oft Gelassenheit oder Entschlossenheit aus: Was auch immer kommt, man bleibt bei seiner Haltung.",
