    "explanation": "动不动 (dòngbudòng) heißt etwa „beim geringsten Anlass“; zusammen mit 就 (jiù) beschreibt es, dass jemand allzu leicht und allzu oft auf eine bestimmte Weise reagiert: 动不动就哭 „heult bei jeder Kleinigkeit“. Das Muster ist umgangssprachlich und fast immer kritisch oder klagend; es beschreibt unerwünschte Gewohnheiten wie 生气 (shēngqì), 发火 (fāhuǒ), 生病 (shēngbìng), 请假 (qǐngjià) oder häufiges Jobwechseln. Für einmalige Ereignisse passt es nicht, ebenso wenig für Lob. 就 gehört fest dazu und steht direkt vor dem Verb. Eine schriftsprachliche Entsprechung ist 动辄 (dòngzhé).",
