    "meaning": "(am Ende) ganz und gar X – lebhaft betontes Ergebnis",
    "formation": "Verb + 得个 + Ergebnis/Zustand (oft Vierzeichenausdruck)",
    "notes": "Ohne 得 steht 个 direkt nach dem Verb (玩个痛快, eigener Punkt Verb + 个 + X); ohne 个 ist 得 + Komplement neutraler (吃得很饱).",
    "explanation": "Zwischen Verb und Ergebniskomplement wird nach 得 (de) ein 个 (ge) eingeschoben. Dadurch wirkt die Beschreibung lebhafter und nachdrücklicher, oft mit einem Unterton von Übertreibung, Spott oder Bedauern: 吃得个精光 „ratzeputz aufgegessen“, 输得个精光 „alles verspielt“. Besonders häufig ist 落得个 (luòde ge) mit einem bitteren Ausgang, etwa „am Ende mit leeren Händen dastehen“ (落得个两手空空) oder mit 下场 (xiàchǎng) „böses Ende“. Auf 得个 folgt meist eine Wendung, die ein vollständiges oder extremes Ergebnis nennt, gern ein Vierzeichenausdruck wie 不欢而散 (bù huān ér sàn) „im Unfrieden auseinandergehen“. Das Muster ist umgangssprachlich-erzählend; statt 得个 hört man auch 了个 (le ge) mit fast gleicher Bedeutung.",
