    "formation": "该 + Verb₁ + (就) + Verb₁，该 + Verb₂ + (就) + Verb₂",
    "notes": "该……了 (HSK 3) heißt „es ist Zeit, dass …“ (该走了); 应该 (yīnggāi) drückt allgemein eine Pflicht aus. Hier geht es dagegen um das jeweils Angemessene in einem Paar von Handlungen.",
    "explanation": "该 (gāi) bedeutet hier „an der Reihe, angebracht sein“. Wird jedes Verb nach 该 (mit oder ohne 就 jiù) wiederholt, entsteht ein Rat oder ein Grundsatz: Tu das, was gerade angebracht ist, ohne Zögern und ohne Übertreibung – 该吃就吃，该睡就睡 „iss, wenn Essenszeit ist, und schlaf, wenn Schlafenszeit ist“. Je nach Zusammenhang klingt das gelassen (sich keine unnötigen Sorgen machen), prinzipientreu (Kritik und Lob, wo sie verdient sind) oder vernünftig im Umgang mit Geld (该花就花，该省就省 „ausgeben, wo nötig, sparen, wo möglich“). Meist stehen zwei, manchmal drei Paare nebeneinander, oft Gegensätze. Ohne 就 wirkt es knapper und umgangssprachlicher. Das Muster ist gesprochen und in Ratgebertexten häufig.",
