    "explanation": "面子 (miànzi) ist das soziale Ansehen, das „Gesicht“ einer Person. 看在 (kàn zài) X 的面子上 heißt wörtlich „im Hinblick auf das Gesicht von X“: Man macht ein Zugeständnis nicht wegen der Sache selbst, sondern aus Rücksicht auf eine dritte Person oder eine Beziehung – „X zuliebe“, „um X willen“. Typisch folgt ein Verzeihen, eine Ausnahme oder ein Gefallen, oft mit 就 (jiù) oder 才 (cái) im zweiten Teil. Als Bitte formuliert man 你就看在我的面子上 … „tu’s mir zuliebe“. Das Muster ist umgangssprachlich und eng mit der chinesischen Vorstellung von Gesicht und Beziehungen verbunden. Gleichbedeutend ist die Variante mit 份上 (fènshang) statt 面子.",
