    "explanation": "Das Suffix 头儿 (tour) macht aus bestimmten einsilbigen Verben ein Nomen für den Wert oder Reiz einer Handlung: 看头儿 (kàntour) „etwas Sehenswertes“, 吃头儿 „etwas, das sich zu essen lohnt“, ebenso 听头儿, 玩头儿 und 逛头儿. Mit 没什么 (méi shénme) davor heißt das Muster: „Es lohnt sich nicht, X zu tun“, „da gibt es nichts zu X“. Das Subjekt ist meist die bewertete Sache – ein Film, ein Ort, ein Gericht, ein Buch. Das Muster ist umgangssprachlich und vor allem im Norden mit 儿 gebräuchlich; geschrieben steht 头 oft auch ohne 儿. Nur eine begrenzte Zahl von Verben bildet solche Nomen, darunter 看, 吃, 听, 玩, 说, 想, 干 und 逛.",
