    "notes": "没什么 (méi shénme) + Verb + 头儿 (tour) bewertet den Reiz einer Sache („nicht sehenswert“), 没什么好 + Verb + 的 eher, ob eine Reaktion nötig ist („kein Grund zu …“).",
    "explanation": "好 (hǎo) steht hier vor einem Verb im Sinn von „lohnend, angebracht“; mit 没什么 (méi shénme) davor und 的 (de) am Ende heißt das Muster: „Es gibt nichts, worüber oder weswegen man X müsste“. Damit beruhigt man (kein Grund zur Sorge), wehrt ab (da gibt es nichts zu sagen) oder beendet entschlossen eine Diskussion (da gibt es nichts zu besprechen). Häufige Verben sind 担心 (dānxīn), 怕, 紧张 (jǐnzhāng), 后悔 (hòuhuǐ), 说, 解释 (jiěshì) und 商量 (shāngliang). 好 kann durch 可 (kě) ersetzt werden. Das Muster ist umgangssprachlich, kommt aber auch in Erzähltexten vor. Die rhetorische Frage 有什么好 … 的？ hat dieselbe Bedeutung, klingt aber vorwurfsvoller.",
