    "explanation": "谈何 (tánhé) heißt wörtlich „wie kann man von … sprechen?“. Es bildet eine rhetorische Frage, die verneint: Das Genannte ist unrealistisch oder unmöglich. Häufig nennt der erste Teilsatz eine fehlende Voraussetzung, oft mit 没有 (méiyǒu) oder 连……都……: „没有信任，谈何合作？“ = „Ohne Vertrauen kann von Zusammenarbeit keine Rede sein.“ Nach 谈何 steht meist ein zweisilbiges Nomen oder Adjektiv wie 发展 (fāzhǎn), 合作 (hézuò), 幸福 (xìngfú). Die bekannteste feste Wendung ist 谈何容易 (tánhé róngyì) „das ist leichter gesagt als getan“. Der Stil ist gehoben (Kommentare, Reden, Aufsätze); gesprochen sagt man eher 还谈什么…… oder 哪儿谈得上…….",
