    "explanation": "Eine feste, parallel gebaute Formel aus der Dienst- und Verwaltungssprache. 所 + Verb macht aus dem Verb ein Nomen „das, was …“: 所想 = „das, was man denkt“; 之 entspricht dem klassischen 的. „想群众之所想“ = „denken, was die Leute denken“, „急群众之所急“ = „das als dringend behandeln, was die Leute drängt“. Gemeint ist: sich in die Lage anderer versetzen und ihre Anliegen sofort angehen. X ist fast immer eine Gruppe, der man dient: 群众 (qúnzhòng), 顾客 (gùkè), 患者 (huànzhě), 用户 (yònghù), 学生 (xuésheng). In beiden Hälften steht dasselbe X. Der Stil ist offiziell und formelhaft (Reden, Berichte, Leitbilder, Werbung); im Alltag wirkt er gestelzt oder ironisch. Manchmal wird die Reihe verlängert, etwa mit 帮X之所需.",
