    "explanation": "要 heißt hier „wenn man … verlangt“: „要钱有钱，要人有人“ = „Geld? Ist da. Leute? Sind da.“ Die positive Form mit 有 lobt, dass jemand oder etwas alles Nötige hat; die negative Form mit 没 klagt, dass es an allem fehlt. X und Y sind Nomen (Geld, Leute, Können, Aussehen …), und in jeder Hälfte wird dasselbe Nomen wiederholt. Häufig folgt eine Schlussfolgerung: 难怪 (nánguài)……, 当然 (dāngrán)……. Die Form ist lebhaft und umgangssprachlich und kann auf drei Glieder erweitert werden. Gelegentlich mischt man scherzhaft beide Formen: „要钱没钱，要脾气有脾气“ = „Geld hat er keins, aber Launen jede Menge“.",
