        "chinese": "这座小城因美丽的湖水而闻名。",
        "pinyin": "Zhè zuò xiǎo chéng yīn měilì de húshuǐ ér wénmíng.",
        "german": "Die kleine Stadt ist für ihren schönen See bekannt."
