    "notes": "Feste Höflichkeitsformel: 有何贵干 (yǒu hé guì gàn) „Was führt Sie zu mir?“. Verwandt: 谈何…… „wie kann man von … reden“, 何必 (hébì) „wozu denn“. Umgangssprachliche Entsprechung: （没）有什么（好）X的.",
    "explanation": "何 (hé) ist die klassische Form von 什么 (shénme); 有何 entspricht also 有什么 in gehobenem Stil. Zwei Gebrauchsweisen: (1) echte, höfliche Frage in formellen Situationen wie Interviews, Sitzungen oder Behörden: 您有何建议？ „Welche Vorschläge haben Sie?“; (2) rhetorische Frage, die verneint: 有何用？ „Was nützt das?“ = es nützt nichts; 有何不可？ „Was spricht dagegen?“ = das geht durchaus. X ist meist zweisilbig oder Teil einer festen Verbindung: 看法 (kànfǎ), 意义 (yìyì), 区别 (qūbié), 感想 (gǎnxiǎng), 不同 (bùtóng), 不妥 (bùtuǒ). Gesprochen sagt man 有什么. Ein zusätzliches 什么 nach 有何 ist falsch.",
