    "explanation": "之余 (zhīyú) bedeutet „was über … hinaus übrig bleibt“. Zwei Gebrauchsweisen: (1) nach einer Tätigkeit wie 工作 (gōngzuò), 学习 (xuéxí) oder 忙碌 (mánglù) „in der freien Zeit neben …“: 工作之余 = „neben der Arbeit, nach Feierabend“; (2) nach einem Gefühl wie 高兴 (gāoxìng), 感动 (gǎndòng) oder 惊讶 (jīngyà) „bei aller …, neben … empfindet man auch …“, oft mit 也 im Hauptsatz. 在 davor ist möglich, aber nicht nötig. Die Fügung steht am Satzanfang und ist eher schriftlich-gehoben; gesprochen sagt man 下班以后, 除了工作以外 oder einfach 高兴是高兴，可是 (kěshì)……. Sie bezeichnet keinen genauen Zeitpunkt; nicht mit Uhrzeiten oder Daten verwenden.",
