    "formation": "值此 + Anlass (Fest, Jubiläum, Ereignis) + 之际，+ Gruß/Dank/Glückwunsch",
    "notes": "Abgrenzung: ……之余 (zhīyú) heißt „neben, in der Zeit nach“ einer Tätigkeit, nicht „anlässlich“.",
    "explanation": "值此 (zhícǐ) heißt „gerade zu dieser Zeit“, 之际 (zhījì) „Zeitpunkt, Moment“. Zusammen leiten sie in feierlichen Texten den Anlass ein: Festtage, Jubiläen, Eröffnungen, Abschlüsse. Im Hauptsatz folgt fast immer ein Gruß, Dank oder Glückwunsch, oft mit 祝, 向……致以 (zhìyǐ)…… oder 向……表示 (biǎoshì)……. Der Anlass ist ein Nomen oder eine kurze Phrase: 新春佳节 (xīnchūn jiājié), 公司成立十周年, 大会召开. Die Formel gehört in Reden, Glückwunschschreiben, Grußkarten und offizielle Briefe; gesprochen sagt man 在……的时候 oder 趁着……. Ohne 值此 kommt auch (在)……之际 vor, das aber nur „zur Zeit von“ bedeutet und weniger feierlich ist.",
