    "notes": "Im Gespräch klingt 一来 (yìlái)……，二来 (èrlái)…… natürlicher. Nicht verwechseln mit 否则 (fǒuzé) „sonst“ oder 原则 (yuánzé) „Prinzip“, die nur das Zeichen 则 teilen.",
