    "notes": "Abgrenzung: 就是说 (jiùshìshuō) „das heißt“ erklärt eine vorige Aussage genauer; 所谓 (suǒwèi) mit 就是 (jiùshì) im zweiten Teil definiert dagegen einen Begriff.",
