    "notes": "Positive Gegenform: 宁可 (nìngkě)……，也要…… „lieber A in Kauf nehmen, um B unbedingt zu erreichen“ (宁可少睡一会儿，也要把工作做完). Abwägung mit 与其 (yǔqí): 与其……，宁愿 (nìngyuàn)/宁可…… „statt A lieber B“ (eigener Punkt).",
    "explanation": "宁可 (nìngkě) und 宁愿 (nìngyuàn) nennen nach einer Abwägung das, was man lieber auf sich nimmt; 也不 (yě bù) nennt das, was man keinesfalls tun will: „我宁可走路，也不坐他的车“ = „Ich gehe lieber zu Fuß, als in sein Auto zu steigen.“ Das gewählte A ist oft selbst unangenehm (hungern, sich abmühen, weniger verdienen) – gerade das zeigt die Entschlossenheit, B abzulehnen. 宁愿 betont etwas stärker den eigenen Willen, meist sind beide austauschbar. Statt 也不 stehen auch 也不愿意, 也不想 oder 决不 (juébù). Das Subjekt steht vor 宁可. Aussprache: 宁 hier im 4. Ton (nìng), nicht níng wie in 安宁 (ānníng).",
