    "explanation": "与其 (yǔqí) nennt die Möglichkeit, die man ablehnt; 宁愿 (nìngyuàn) oder 宁可 (nìngkě) leitet ein, was man stattdessen tun will – oft etwas, das selbst unangenehm ist, aber bewusst in Kauf genommen wird: „statt A nehme ich lieber B auf mich“. Im Unterschied zu 不如 (bùrú) in 与其……不如…… („B ist einfach die bessere Wahl“) betont 宁愿/宁可 die feste persönliche Entscheidung des Sprechers. Das Subjekt steht meist vor 宁愿/宁可 im zweiten Teil. Gehoben, in Rede und Schrift; 宁可 und 宁愿 sind hier austauschbar. Fehler: 与其 ohne Gegenstück (宁愿/宁可/不如) stehen lassen.",
    "notes": "Ohne 与其 (yǔqí) lautet die verwandte Form 宁可 (nìngkě)/宁愿 (nìngyuàn)……，也不……: Dort steht die gewählte Möglichkeit vorn, die abgelehnte mit 也不 hinten. Mit 不如 (bùrú) statt 宁愿/宁可 wägt der Satz sachlich ab („es ist besser, …“); 与其说……不如说…… korrigiert eine Beschreibung („eher … als …“).",
