    "explanation": "Ein Wort X (meist Adjektiv oder Verb) wird um 是 herum wiederholt: „X 是 X“ gibt zu, dass X zutrifft, der zweite Teil bringt mit 可是 (kěshì), 但是 (dànshì), 就是 (jiùshì), 不过 (búguò) oder 却 die eigentliche Einschränkung. 倒 (dào) vor 是 macht das Zugeständnis betonter („das schon, aber …“). 了 nach dem zweiten X steht bei abgeschlossenen Handlungen oder eingetretenen Veränderungen: 去是去了 „hingegangen bin ich ja“, 便宜是便宜了 „billiger ist es schon geworden“. Typisch gesprochen. Fehler: den zweiten Teil weglassen – der Satz klingt dann unvollständig, weil die Einschränkung erwartet wird.",
