    "formation": "别看 + äußerer Eindruck，(Subjekt +) 可/却/其实 + tatsächlicher Sachverhalt",
    "notes": "别看 (biékàn) ist kein Verbot „schau nicht hin“, sondern ein Bindewort; der Satz braucht deshalb den korrigierenden zweiten Teil. Abgrenzung: 虽然 (suīrán)/虽说 (suīshuō) räumen neutral ein, 别说 (biéshuō) steigert dagegen („geschweige denn“).",
    "explanation": "别看 (biékàn) heißt wörtlich „schau nicht darauf, dass …“: Der erste Teil nennt einen Eindruck oder eine Tatsache, aus der man etwas Falsches schließen könnte; der zweite Teil stellt das Gegenteil richtig. Anders als bei 虽然 (suīrán) liegt der Ton auf der Warnung vor einem voreiligen Urteil („man sollte nicht meinen, dass …“). Im zweiten Teil stehen oft 可, 却, 其实 (qíshí) oder 还, ein Bindewort ist aber nicht nötig. Typisch gesprochen und lebendig, auch in Erzähltexten. Das Subjekt ist meist eine Person oder Sache, über die man sich leicht täuscht.",
