    "explanation": "虽说 (suīshuō) entspricht inhaltlich 虽然 (suīrán): Der erste Teil räumt eine Tatsache ein, der zweite bringt mit 但 (dàn) oder 可 (kě) – auch 但是 (dànshì), 可是 (kěshì) – die Gegenaussage. 虽说 klingt etwas lockerer und abwägender, etwa „man kann zwar sagen, dass …“, und kommt in Gesprächen wie in erzählender Prosa vor. Im zweiten Teil stehen oft zusätzlich 还是 (háishi), 也 oder 却. Die eingeräumte Aussage ist eine Tatsache, keine bloße Annahme – für Hypothesen nimmt man 即使 (jíshǐ) oder 哪怕 (nǎpà). 虽说 steht meist am Satzanfang, kann aber auch hinter dem Subjekt stehen.",
