    "explanation": "与否 (yǔfǒu) bedeutet „oder nicht“ und steht hinter einem meist zweisilbigen Verb oder Adjektiv: 成功与否 „ob erfolgreich oder nicht“, 同意与否 „ob einverstanden oder nicht“. Zusammen mit 无论 (wúlùn) heißt das: Beide Möglichkeiten führen zur selben Folge, die mit 都 eingeleitet wird. Die Form ist schriftsprachlich und förmlich (Bekanntmachungen, Reden, Berichte); im Gespräch sagt man eher 不管 (bùguǎn)……不……，都…… (不管成功不成功). Typische Fehler: 与否 mit der Ja-Nein-Form verdoppeln (成功不成功与否) oder es hinter ein langes Verb mit Objekt hängen. Statt 无论 kommt auch 不论 (búlùn) vor.",
