    "explanation": "凡 (fán) heißt „jeder, der … / alle, die …“ und grenzt eine Gruppe ein, für die eine Regel ohne Ausnahme gilt. 者 (zhě) macht aus einer Beschreibung eine Person („derjenige, der“): 年满十八岁者 „wer 18 Jahre alt ist“. 均 (jūn) ist das schriftliche „alle, ausnahmslos“ und entspricht 都; mit 可 (kě) wird daraus eine Erlaubnis („dürfen alle …“). Die Form ist typisch für Bekanntmachungen, Regeln, Ausschreibungen und Verträge, im Alltag klingt sie steif. Gesprochen sagt man 凡是 (fánshì)……都……. Wenn statt 者 ein Nomen folgt (凡……的顾客), fällt 者 weg.",
