    "explanation": "别说 (biéshuō) heißt „ganz zu schweigen von“: Der erste Teil nennt den Fall, für den die Aussage offensichtlich gilt (oder offensichtlich nicht gilt); der zweite Teil zeigt mit 都 oder 也, dass sie sogar für einen Fall gilt, bei dem man es am wenigsten erwarten würde – oft verstärkt durch 连 oder 就是 (jiùshì). Beispiel: 别说一百块，一块钱都没有 „von hundert ganz zu schweigen – nicht einmal einen Yuan“. Am Ende des ersten Teils steht häufig 了. Die Form ist vor allem gesprochen. Typischer Fehler: die Fälle vertauschen – hinter 别说 gehört der Fall, der ohnehin klar ist.",
