    "meaning": "aus Gründen der … / sicherheitshalber, der Einfachheit halber",
    "formation": "为(了) + Zweck (meist zweisilbiges Adjektiv/Nomen) + 起见，Maßnahme",
    "notes": "Allgemeine Zweckangaben mit Verbgruppe macht man mit 为了 (wèile)……，…… (HSK 3). 为 heißt hier wèi (4. Ton), nicht wéi.",
    "explanation": "起见 (qǐjiàn) schließt eine Zweckangabe mit 为 (wèi) oder 为了 (wèile) ab: „im Interesse von …, um … willen“. Zwischen 为 und 起见 stehen fast nur kurze abstrakte Wörter wie 安全 (ānquán), 方便 (fāngbiàn), 慎重 (shènzhòng), 保险 (bǎoxiǎn), 稳妥 (wěntuǒ), 公平 (gōngpíng) – keine längeren Verbgruppen (nicht *为了学好汉语起见). Der Teil steht vor der Hauptaussage, die eine Maßnahme, Bitte oder Entscheidung nennt. Die Form ist förmlich und typisch für Hinweise, Anweisungen, Berichte und Vorworte; sie kommt aber auch in sorgfältiger Rede vor (为了保险起见 „sicherheitshalber“).",
    "examples": [
      {
        "chinese": "为安全起见，请不要在车内吸烟。",
        "pinyin": "Wèi ānquán qǐjiàn, qǐng búyào zài chē nèi xīyān.",
        "german": "Aus Sicherheitsgründen bitte im Fahrzeug nicht rauchen."
      },
      {
        "chinese": "为了慎重起见，我们决定再讨论一次。",
        "pinyin": "Wèile shènzhòng qǐjiàn, wǒmen juédìng zài tǎolùn yí cì.",
        "german": "Um ganz sorgfältig zu sein, haben wir beschlossen, es noch einmal zu besprechen."
      },
      {
        "chinese": "为方便起见，文中的人名都用了简称。",
        "pinyin": "Wèi fāngbiàn qǐjiàn, wén zhōng de rénmíng dōu yòng le jiǎnchēng.",
        "german": "Der Einfachheit halber sind die Namen im Text abgekürzt."
      }
    ],
