    "explanation": "以 (yǐ) am Anfang des zweiten Teilsatzes bedeutet „um damit …, auf dass …“ und nennt den Zweck der vorher genannten Handlung – inhaltlich wie 以便 (yǐbiàn) oder 为的是 (wèi de shì). Der erste Teil beschreibt eine Maßnahme, der zweite das Ziel, meist mit Verben wie 满足 (mǎnzú), 保证 (bǎozhèng), 确保 (quèbǎo), 提高 (tígāo), 鼓励 (gǔlì), 促进 (cùjìn). Die Form ist knapp und schriftsprachlich (Behördentexte, Nachrichten, Berichte); im Gespräch sagt man eher 好 oder 为了 (wèile). Das Subjekt beider Teile ist dasselbe und wird im zweiten Teil nicht wiederholt.",
