    "formation": "任 + Person + 怎么/再/Fragewort + Verb/Adjektiv，(Subjekt +) 也 + unveränderte Folge",
    "notes": "任 als Verb heißt auch „ernennen“, etwa in 任命 (rènmìng), oder „gewähren lassen“; im Muster ist es ein Bindewort. Abgrenzung: 再……也…… (HSK 5) braucht kein 任.",
    "explanation": "任 (rèn) bedeutet hier „lass … nur, ganz gleich …“ und entspricht 不管 (bùguǎn)/无论 (wúlùn): Was auch immer im ersten Teil geschieht, der zweite Teil mit 也 (seltener 都) bleibt unverändert, meist verneint. Im ersten Teil steht fast immer 怎么 (zěnme), 再, 谁 oder ein anderes Fragewort: 任你怎么劝 „du kannst ihm zureden, so viel du willst“. Als zusammengezogener Satz (紧缩复句) erscheint die Form auch ohne Komma: 任谁来说情也没用. Die Form klingt leicht gehoben bis literarisch, im Gespräch nachdrücklich. Gleichbedeutend, aber länger ist 任凭 (rènpíng).",
