    "meaning": "Mehrfach-Satzgefüge, oberste Ebene nebenordnend (A und B, darin weitere Beziehungen)",
    "formation": "[Teil A: selbst ein Satzgefüge]；[Teil B: selbst ein Satzgefüge] – oberste Ebene: Reihung oder Gegenüberstellung",
    "notes": "Die einfachen zweiteiligen Satzgefüge mit 也, mit 一边 (yìbiān) … 一边 oder mit 一方面 (yì fāngmiàn) … 另一方面 (lìng yì fāngmiàn) sind eigene Punkte. Die anderen Mehrfach-Satzgefüge sind nach ihrer obersten Ebene benannt: 转折 (zhuǎnzhé) „Gegensatz“, 假设 (jiǎshè) „Annahme“, 因果 (yīnguǒ) „Grund und Folge“, 递进 (dìjìn) „Steigerung“.",
    "explanation": "Ein 多重复句 (duōchóng fùjù) hat mindestens zwei Ebenen: Die Teilsätze bilden zuerst kleinere Gruppen, die dann ihrerseits verbunden werden. Den Namen gibt immer die oberste Ebene, also die erste große Bruchstelle des Satzes. Beim 多重并列复句 (duōchóng bìngliè fùjù) stehen auf dieser obersten Ebene zwei oder mehr gleichrangige Teile nebeneinander – oft durch ein Semikolon (；) getrennt oder mit 一方面 (yì fāngmiàn) … 另一方面 (lìng yì fāngmiàn), 也, 同时 (tóngshí) verbunden. Innerhalb jedes Teils gelten weitere Beziehungen: Gegensatz mit 虽然 (suīrán) … 但是 (dànshì), Steigerung mit 不但 (búdàn) … 而且 (érqiě), Bedingung, Grund. Beim Lesen sucht man zuerst die Hauptbruchstelle, dann die inneren Beziehungen. Solche Sätze sind typisch für Schriftsprache, Berichte und Aufsätze. Häufiger Fehler: Bindewörter der inneren Ebene so zu lesen, als bezögen sie sich auf den ganzen Satz.",
    "examples": [
      {
        "chinese": "这家饭馆的菜虽然不便宜，但是味道很好；服务员不但热情，而且动作很快。",
        "pinyin": "Zhè jiā fànguǎn de cài suīrán bù piányi, dànshì wèidào hěn hǎo; fúwùyuán búdàn rèqíng, érqiě dòngzuò hěn kuài.",
        "german": "Das Essen in diesem Restaurant ist zwar nicht billig, schmeckt aber sehr gut; die Kellner sind nicht nur freundlich, sondern auch sehr flink."
      },
      {
        "chinese": "一方面，因为工作太忙，他很少回家；另一方面，因为身体不好，他父母也不能常来看他。",
        "pinyin": "Yì fāngmiàn, yīnwèi gōngzuò tài máng, tā hěn shǎo huí jiā; lìng yì fāngmiàn, yīnwèi shēntǐ bù hǎo, tā fùmǔ yě bù néng cháng lái kàn tā.",
        "german": "Zum einen kommt er selten nach Hause, weil er so viel Arbeit hat; zum anderen können seine Eltern ihn nicht oft besuchen, weil es ihnen gesundheitlich nicht gut geht."
      },
      {
        "chinese": "如果明天天气好，我们就去爬山；如果下雨，我们就在家看电影。",
        "pinyin": "Rúguǒ míngtiān tiānqì hǎo, wǒmen jiù qù pá shān; rúguǒ xià yǔ, wǒmen jiù zài jiā kàn diànyǐng.",
        "german": "Wenn morgen schönes Wetter ist, gehen wir wandern; wenn es regnet, schauen wir zu Hause einen Film."
      }
    ],
    "quiz": {
      "example": 1,
      "answer": "另一方面",
      "distractors": [
        {
          "text": "但是",
          "reason": "但是 leitet einen Gegensatz ein; die beiden Hälften stehen hier gleichrangig nebeneinander („zum anderen“)."
        },
        {
          "text": "所以",
          "reason": "所以 macht die zweite Hälfte zur Folge der ersten; hier wird aber ein zweiter, gleichrangiger Gesichtspunkt angefügt."
        },
        {
          "text": "其次",
          "reason": "其次 gehört zu 首先……其次…… (Rangfolge); 一方面 verlangt als Gegenstück 另一方面."
        }
      ]
    },
