        "pinyin": "Jiǎrú zhè cì tánpàn shībài le, gōngsī búdàn huì shīqù zhège kèhù, érqiě kěnéng hái yào péicháng duìfāng de sǔnshī.",
        "german": "Sollten die Verhandlungen diesmal scheitern, würde die Firma nicht nur diesen Kunden verlieren, sondern müsste womöglich auch noch den Schaden der Gegenseite ersetzen."
