    "explanation": "In einem Abschnitt, 语段 (yǔduàn), oder einer Satzgruppe, 句群 (jùqún), werden die Sätze hier so angeordnet, wie die Ereignisse aufeinander folgen. Das Chinesische hält sich dabei strenger an die Zeitfolge als das Deutsche: Was zuerst geschieht, wird zuerst gesagt. Zusammengehalten wird der Abschnitt durch Zeitangaben wie 那天 (nà tiān), 三年后 oder 第二天 (dì-èr tiān) und Wörter der Abfolge: 先 (xiān) „zuerst“, 接着 (jiēzhe) „gleich danach“, 然后 (ránhòu) „dann“, 后来 (hòulái) „später (in der Vergangenheit)“, 最后 (zuìhòu) „zum Schluss“, 于是 (yúshì) „daraufhin“. Typisch ist das für Erzählungen, Lebensläufe, Berichte und Anleitungen. Häufige Fehler: 后来 für Zukünftiges oder Anleitungen verwenden (dort steht 然后 oder 以后 (yǐhòu)), und Ereignisse wie im Deutschen nachträglich einschieben, statt sie in der richtigen Reihenfolge zu erzählen.",
