    "explanation": "Bei Beschreibungen von Wohnungen, Gebäuden, Städten oder Landschaften folgen die Sätze einem räumlichen Weg: von außen nach innen, von nah nach fern, von unten nach oben, von links nach rechts oder so, wie man beim Gehen die Dinge sieht. Jeder Satz beginnt meist mit einer Orts- oder Richtungsangabe wie 进门 (jìn mén), 左边 (zuǒbian), 再往前走 oder 山顶上, danach folgt, was sich dort befindet – oft als Existenzsatz mit 是, 有 oder Verb + 着: 墙上挂着一张地图. Wichtig ist eine feste Blickrichtung: Der Leser soll sich den Raum Schritt für Schritt vorstellen können, ohne dass der Text hin und her springt. Bezugsorte werden wieder aufgenommen (客厅 (kètīng) …，客厅左边 …), damit klar bleibt, wovon aus die Richtung gilt. In solchen Beschreibungen steht der Ort meist vorn (左边是厨房), weil er an den vorigen Satz anknüpft; 厨房在左边 ist zwar richtig, unterbricht aber den räumlichen Faden.",
