    "notes": "Zeitliche (时间顺序) und räumliche Anordnung (空间顺序) sind Nachbarpunkte. Die Paare 首先 (shǒuxiān) … 其次 (qícì) und 一方面 (yì fāngmiàn) … 另一方面 (lìng yì fāngmiàn) sind eigene Punkte, 总之 (zǒngzhī) ebenfalls.",
    "explanation": "Hier folgt der Abschnitt nicht der Zeit oder dem Raum, sondern der Sachlogik. Häufige Muster: vom Allgemeinen zum Besonderen (erst die These, dann die Einzelpunkte), von der Erscheinung zur Ursache, von der Ursache zur Folge, vom Problem zur Lösung, vom Wichtigeren zum weniger Wichtigen. Zusammengehalten wird der Abschnitt durch Ordnungs- und Folgewörter: 首先 (shǒuxiān) „erstens“, 其次 (qícì) „zweitens“, 一是……二是…… „zum einen …, zum anderen …“, 另外 (lìngwài) „außerdem“, 因此 (yīncǐ) „deshalb“, 可见 (kějiàn) „daraus sieht man“, 总之 (zǒngzhī) „kurzum“. Diese Ordnung ist typisch für Erörterungen, Stellungnahmen, Reden und die Schreibaufgaben der höheren HSK-Stufen. Fehler: zeitliche Wörter wie 然后 (ránhòu) oder 后来 (hòulái) für Argumente benutzen, Ordnungswörter mischen (首先……然后……第三……) oder den Schluss ohne Folgewort anhängen.",
