        "pinyin": "Běijīng yǒu hěn duō yǒumíng de gōngyuán, qízhōng zuì yǒumíng de shì Yíhéyuán. Yíhéyuán yuánlái shì huángjiā yuánlín, xiànzài měi tiān dōu yǒu dàliàng yóukè lái zhèli cānguān.",
