    "explanation": "Soll ein neues Thema beginnen, kündigt man den Wechsel meist an, damit er nicht abrupt wirkt. Typische Überleitungen: 另外 (lìngwài) und 此外 (cǐwài) „außerdem, noch etwas“ (sachlich, auch schriftlich); 至于 (zhìyú) „was … betrifft“ für einen anschließenden Teilaspekt; 对了 (duìle) „ach übrigens, ach ja“ für einen plötzlichen Einfall im Gespräch; 顺便问一下 (shùnbiàn wèn yíxià) „nebenbei gefragt“. Oft wird das bisherige Thema vorher abgeschlossen (这件事就这么定了 / 今天就到这里). Danach wird das neue Thema ausdrücklich genannt, meist als Nomen am Satzanfang. Gesprochen wirken 对了 und 好了 natürlich, schriftlich eher 此外 und 至于. Fehler: ohne jede Überleitung zu etwas völlig anderem springen, oder 至于 für ein ganz fremdes Thema verwenden – es leitet zu etwas über, das mit dem Vorigen zusammenhängt.",
